window.BOOK2_READING_ALIGNMENT={"version":1,"label":"逐句自编中文译文（非教材官方译文）","source":"book2-lessons.js / existing self-authored Chinese translations","reviewStatus":"self-reviewed-with-independent-cross-check","status":{"book":2,"lessons":96,"sentences":1055},"lessons":[{"lessonId":"nce-b2-eef57c-l001","number":1,"book":2,"title":"A private conversation","paragraphs":[{"index":0,"rows":[{"en":"Last week I went to the theatre.","zh":"上周我去看戏了。","kind":"narration","speaker":"旁白"},{"en":"I had a very good seat.","zh":"我的座位很好。","kind":"narration","speaker":"旁白"},{"en":"The play was very interesting.","zh":"这出戏很有意思。","kind":"narration","speaker":"旁白"},{"en":"I did not enjoy it.","zh":"可我却没能欣赏这出戏。","kind":"narration","speaker":"旁白"},{"en":"A young man and a young woman were sitting behind me.","zh":"一名年轻男子和一名年轻女子坐在我身后。","kind":"narration","speaker":"旁白"},{"en":"They were talking loudly.","zh":"他们大声地说着话。","kind":"narration","speaker":"旁白"},{"en":"I got very angry.","zh":"我非常生气。","kind":"narration","speaker":"旁白"},{"en":"I could not hear the actors.","zh":"我听不见演员的声音。","kind":"narration","speaker":"旁白"},{"en":"I turned round.","zh":"我转过身去。","kind":"narration","speaker":"旁白"},{"en":"I looked at the man and the woman angrily.","zh":"我生气地看着那一男一女。","kind":"narration","speaker":"旁白"},{"en":"They did not pay any attention.","zh":"他们毫不理会。","kind":"narration","speaker":"旁白"},{"en":"In the end, I could not bear it.","zh":"最后，我实在忍不住了。","kind":"narration","speaker":"旁白"},{"en":"I turned round again.","zh":"我又转过身去。","kind":"narration","speaker":"旁白"},{"en":"‘I can’t hear a word!’ I said angrily.","zh":"“我一个字也听不见！”我生气地说。","kind":"speech","speaker":"我","breakBefore":true}]},{"index":1,"rows":[{"en":"‘It’s none of your business,’ the young man said rudely.","zh":"“这不关你的事，”那名年轻男子无礼地说。","kind":"speech","speaker":"年轻男子"},{"en":"‘This is a private conversation!’","zh":"“这是私人谈话！”","kind":"speech","speaker":"年轻男子"}]}]},{"lessonId":"nce-b2-eef57c-l002","number":2,"book":2,"title":"Breakfast or lunch?","paragraphs":[{"index":0,"rows":[{"en":"It was Sunday.","zh":"那天是星期天。","kind":"narration","speaker":"旁白"},{"en":"I never get up early on Sundays.","zh":"我星期天从不早起。","kind":"narration","speaker":"旁白"},{"en":"I sometimes stay in bed until lunchtime.","zh":"有时我一直躺在床上，直到吃午饭的时候。","kind":"narration","speaker":"旁白"},{"en":"Last Sunday I got up very late.","zh":"上个星期天，我起得很晚。","kind":"narration","speaker":"旁白"},{"en":"I looked out of the window.","zh":"我朝窗外望去。","kind":"narration","speaker":"旁白"},{"en":"It was dark outside.","zh":"外面一片昏暗。","kind":"narration","speaker":"旁白"},{"en":"‘What a day!’ I thought.","zh":"“这是什么天气啊！”我心想。","kind":"thought","speaker":"我","breakBefore":true},{"en":"‘It’s raining again.’","zh":"“又在下雨了。”","kind":"thought","speaker":"我"},{"en":"Just then, the telephone rang.","zh":"就在这时，电话响了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It was my aunt Lucy.","zh":"是我露西阿姨打来的。","kind":"narration","speaker":"旁白"},{"en":"‘I’ve just arrived by train,’ she said.","zh":"“我刚坐火车到，”她说。","kind":"speech","speaker":"露西阿姨","breakBefore":true},{"en":"‘I'm coming to see you.’","zh":"“我这就来看你。”","kind":"speech","speaker":"露西阿姨"}]},{"index":1,"rows":[{"en":"‘But I'm still having breakfast,’ I said.","zh":"“可我还在吃早饭呢，”我说。","kind":"speech","speaker":"我"}]},{"index":2,"rows":[{"en":"‘What are you doing?’ she asked.","zh":"“你在干什么？”她问。","kind":"speech","speaker":"露西阿姨"}]},{"index":3,"rows":[{"en":"‘I'm having breakfast,’ I repeated.","zh":"“我在吃早饭，”我又说了一遍。","kind":"speech","speaker":"我"}]},{"index":4,"rows":[{"en":"‘Dear me,’ she said.","zh":"“天哪，”她说。","kind":"speech","speaker":"露西阿姨"},{"en":"‘Do you always get up so late?","zh":"“你总是起得这么晚吗？”","kind":"speech","speaker":"露西阿姨"},{"en":"It’s one o’clock!’","zh":"“现在已经一点了！”","kind":"speech","speaker":"露西阿姨"}]}]},{"lessonId":"nce-b2-eef57c-l003","number":3,"book":2,"title":"Please send me a card","paragraphs":[{"index":0,"rows":[{"en":"Postcards always spoil my holidays.","zh":"明信片总会搅乱我的假期。","kind":"narration","speaker":"旁白"},{"en":"Last summer, I went to Italy.","zh":"去年夏天，我去了意大利。","kind":"narration","speaker":"旁白"},{"en":"I visited museums and sat in public gardens.","zh":"我参观了博物馆，也在公园里坐了坐。","kind":"narration","speaker":"旁白"},{"en":"A friendly waiter taught me a few words of Italian.","zh":"一位友好的服务员教了我几个意大利语词。","kind":"narration","speaker":"旁白"},{"en":"Then he lent me a book.","zh":"随后，他借给我一本书。","kind":"narration","speaker":"旁白"},{"en":"I read a few lines, but I did not understand a word.","zh":"我读了几行，却一个字也不懂。","kind":"narration","speaker":"旁白"},{"en":"Every day I thought about postcards.","zh":"每天我都想着明信片的事。","kind":"narration","speaker":"旁白"},{"en":"My holidays passed quickly, but I did not send cards to my friends.","zh":"假期很快就过去了，可我没有给朋友们寄明信片。","kind":"narration","speaker":"旁白"},{"en":"On the last day I made a big decision.","zh":"最后一天，我作出了一个重大决定。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"I got up early and bought thirty-seven cards.","zh":"我早早起床，买了三十七张明信片。","kind":"narration","speaker":"旁白"},{"en":"I spent the whole day in my room, but I did not write a single card!","zh":"我在房间里待了一整天，却连一张明信片也没写！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l004","number":4,"book":2,"title":"An exciting trip","paragraphs":[{"index":0,"rows":[{"en":"I have just received a letter from my brother, Tim.","zh":"我刚收到我的兄弟蒂姆的一封信。","kind":"narration","speaker":"旁白"},{"en":"He is in Australia.","zh":"他在澳大利亚。","kind":"narration","speaker":"旁白"},{"en":"He has been there for six months.","zh":"他已经在那里待了六个月。","kind":"narration","speaker":"旁白"},{"en":"Tim is an engineer.","zh":"蒂姆是一名工程师。","kind":"narration","speaker":"旁白"},{"en":"He is working for a big firm and he has already visited a great number of different places in Australia.","zh":"他在一家大公司工作，而且已经去过澳大利亚许多不同的地方。","kind":"narration","speaker":"旁白"},{"en":"He has just bought an Australian car and has gone to Alice Springs, a small town in the centre of Australia.","zh":"他刚买了一辆澳大利亚产的汽车，并且已经去了澳大利亚中部的小镇艾丽斯斯普林斯。","kind":"narration","speaker":"旁白"},{"en":"He will soon visit Darwin.","zh":"他不久就要去达尔文。","kind":"narration","speaker":"旁白"},{"en":"From there, he will fly to Perth.","zh":"从那里，他将乘飞机去珀斯。","kind":"narration","speaker":"旁白"},{"en":"My brother has never been abroad before, so he is finding this trip very exciting.","zh":"我的兄弟以前从未出过国，因此他觉得这次旅行十分令人兴奋。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l005","number":5,"book":2,"title":"No wrong numbers","paragraphs":[{"index":0,"rows":[{"en":"Mr. James Scott has a garage in Silbury and now he has just bought another garage in Pinhurst.","zh":"詹姆斯·斯科特先生在锡尔伯里有一家汽车修理厂，现在他刚在平赫斯特又买下了一家。","kind":"narration","speaker":"旁白"},{"en":"Pinhurst is only five miles from Silbury, but Mr. Scott cannot get a telephone for his new garage, so he has just bought twelve pigeons.","zh":"平赫斯特离锡尔伯里只有五英里，可斯科特先生的新修理厂装不上电话，因此他刚买了十二只鸽子。","kind":"narration","speaker":"旁白"},{"en":"Yesterday, a pigeon carried the first message from Pinhurst to Silbury.","zh":"昨天，一只鸽子把第一条消息从平赫斯特送到了锡尔伯里。","kind":"narration","speaker":"旁白"},{"en":"The bird covered the distance in three minutes.","zh":"这只鸽子只用了三分钟就飞完了这段路。","kind":"narration","speaker":"旁白"},{"en":"Up to now, Mr. Scott has sent a great many requests for spare parts and other urgent messages from one garage to the other.","zh":"到目前为止，斯科特先生已经在两家修理厂之间传递了许多索取零配件的请求和其他紧急消息。","kind":"narration","speaker":"旁白"},{"en":"In this way, he has begun his own private ‘telephone’ service.","zh":"就这样，他开办起了自己的私人“电话”服务。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l006","number":6,"book":2,"title":"Percy Buttons","paragraphs":[{"index":0,"rows":[{"en":"I have just moved to a house in Bridge Street.","zh":"我刚搬进桥街的一所房子。","kind":"narration","speaker":"旁白"},{"en":"Yesterday a beggar knocked at my door.","zh":"昨天，一个乞丐敲了我的门。","kind":"narration","speaker":"旁白"},{"en":"He asked me for a meal and a glass of beer.","zh":"他向我要一顿饭和一杯啤酒。","kind":"narration","speaker":"旁白"},{"en":"In return for this, the beggar stood on his head and sang songs.","zh":"作为回报，这个乞丐倒立着唱起歌来。","kind":"narration","speaker":"旁白"},{"en":"I gave him a meal.","zh":"我给了他一顿饭。","kind":"narration","speaker":"旁白"},{"en":"He ate the food and drank the beer.","zh":"他吃了饭，喝了啤酒。","kind":"narration","speaker":"旁白"},{"en":"Then he put a piece of cheese in his pocket and went away.","zh":"随后，他把一块奶酪放进口袋，走了。","kind":"narration","speaker":"旁白"},{"en":"Later a neighbour told me about him.","zh":"后来，一位邻居向我说起了他的事。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Everybody knows him.","zh":"大家都认识他。","kind":"narration","speaker":"旁白"},{"en":"His name is Percy Buttons.","zh":"他叫珀西·巴顿斯。","kind":"narration","speaker":"旁白"},{"en":"He calls at every house in the street once a month and always asks for a meal and a glass of beer.","zh":"他每个月都到这条街上的每一家去一次，而且总是要一顿饭和一杯啤酒。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l007","number":7,"book":2,"title":"Too late","paragraphs":[{"index":0,"rows":[{"en":"The plane was late and detectives were waiting at the airport all morning.","zh":"飞机晚点了，侦探们整个上午都在机场等候。","kind":"narration","speaker":"旁白"},{"en":"They were expecting a valuable parcel of diamonds from South Africa.","zh":"他们在等一个从南非运来的贵重钻石包裹。","kind":"narration","speaker":"旁白"},{"en":"A few hours earlier, someone had told the police that thieves would try to steal the diamonds.","zh":"几小时前，有人告诉警方，窃贼会设法偷走这些钻石。","kind":"narration","speaker":"旁白"},{"en":"When the plane arrived, some of the detectives were waiting inside the main building while others were waiting on the airfield.","zh":"飞机到达时，有些侦探在主楼里等候，另一些则在停机坪上等候。","kind":"narration","speaker":"旁白"},{"en":"Two men took the parcel off the plane and carried it into the Customs House.","zh":"两个人把包裹从飞机上取下来，搬进了海关大楼。","kind":"narration","speaker":"旁白"},{"en":"While two detectives were keeping guard at the door, two others opened the parcel.","zh":"两名侦探在门口警戒时，另外两名打开了包裹。","kind":"narration","speaker":"旁白"},{"en":"To their surprise, the precious parcel was full of stones and sand!","zh":"令他们吃惊的是，这个贵重的包裹里装的竟然全是石头和沙子！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l008","number":8,"book":2,"title":"The best and the worst","paragraphs":[{"index":0,"rows":[{"en":"Joe Sanders has the most beautiful garden in our town.","zh":"乔·桑德斯拥有我们镇上最漂亮的花园。","kind":"narration","speaker":"旁白"},{"en":"Nearly everybody enters for ‘The Nicest Garden Competition’ each year, but Joe wins every time.","zh":"每年几乎人人都报名参加“最佳花园竞赛”，但每次都是乔获胜。","kind":"narration","speaker":"旁白"},{"en":"Bill Frith’s garden is larger than Joe's.","zh":"比尔·弗里思的花园比乔的更大。","kind":"narration","speaker":"旁白"},{"en":"Bill works harder than Joe and grows more flowers and vegetables, but Joe’s garden is more interesting.","zh":"比尔比乔干活更卖力，种的花和蔬菜也更多，可乔的花园更有趣味。","kind":"narration","speaker":"旁白"},{"en":"He has made neat paths and has built a wooden bridge over a pool.","zh":"他修建了整齐的小径，还在池塘上搭了一座木桥。","kind":"narration","speaker":"旁白"},{"en":"I like gardens too, but I do not like hard work.","zh":"我也喜欢花园，可我不喜欢辛苦劳动。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Every year I enter for the garden competition too, and I always win a little prize for the worst garden in the town!","zh":"每年我也参加花园竞赛，而且总会因为拥有镇上最差的花园而获得一个小奖！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l009","number":9,"book":2,"title":"A cold welcome","paragraphs":[{"index":0,"rows":[{"en":"On Wednesday evening, we went to the Town Hall.","zh":"星期三晚上，我们去了市政厅。","kind":"narration","speaker":"旁白"},{"en":"It was the last day of the year and a large crowd of people had gathered under the Town Hall clock.","zh":"那是一年的最后一天，一大群人聚集在市政厅的大钟下面。","kind":"narration","speaker":"旁白"},{"en":"It would strike twelve in twenty minutes’ time.","zh":"再过二十分钟，大钟就要敲响十二点了。","kind":"narration","speaker":"旁白"},{"en":"Fifteen minutes passed and then, at five to twelve, the clock stopped.","zh":"十五分钟过去了，接着，在差五分钟到十二点时，钟停了。","kind":"narration","speaker":"旁白"},{"en":"The big minute hand did not move.","zh":"巨大的分针一动不动。","kind":"narration","speaker":"旁白"},{"en":"We waited and waited, but nothing happened.","zh":"我们等了又等，可始终没有动静。","kind":"narration","speaker":"旁白"},{"en":"Suddenly someone shouted, ‘It’s two minutes past twelve!","zh":"突然有人喊道：“已经十二点零两分了！”","kind":"mixed","speaker":"旁白与喊话的人","breakBefore":true},{"en":"The clock has stopped!’","zh":"“钟停了！”","kind":"speech","speaker":"喊话的人"},{"en":"I looked at my watch.","zh":"我看了看手表。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It was true.","zh":"确实如此。","kind":"narration","speaker":"旁白"},{"en":"The big clock refused to welcome the New Year.","zh":"那座大钟偏偏不肯迎接新年。","kind":"narration","speaker":"旁白"},{"en":"At that moment, everybody began to laugh and sing.","zh":"就在这时，大家都开始笑起来、唱起来。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l010","number":10,"book":2,"title":"Not for jazz","paragraphs":[{"index":0,"rows":[{"en":"We have an old musical instrument.","zh":"我们家有一件古老的乐器。","kind":"narration","speaker":"旁白"},{"en":"It is called a clavichord.","zh":"它叫作击弦古钢琴。","kind":"narration","speaker":"旁白"},{"en":"It was made in Germany in 1681.","zh":"它是一六八一年在德国制造的。","kind":"narration","speaker":"旁白"},{"en":"Our clavichord is kept in the living room.","zh":"我们家的击弦古钢琴放在客厅里。","kind":"narration","speaker":"旁白"},{"en":"It has belonged to our family for a long time.","zh":"它属于我们家已经很长时间了。","kind":"narration","speaker":"旁白"},{"en":"The instrument was bought by my grandfather many years ago.","zh":"这件乐器是我祖父许多年前买的。","kind":"narration","speaker":"旁白"},{"en":"Recently it was damaged by a visitor.","zh":"最近，它被一位来访的客人弄坏了。","kind":"narration","speaker":"旁白"},{"en":"She tried to play jazz on it!","zh":"她竟想用它弹爵士乐！","kind":"narration","speaker":"旁白"},{"en":"She struck the keys too hard and two of the strings were broken.","zh":"她敲击琴键太用力，弄断了两根琴弦。","kind":"narration","speaker":"旁白"},{"en":"My father was shocked.","zh":"我父亲大为震惊。","kind":"narration","speaker":"旁白"},{"en":"Now we are not allowed to touch it.","zh":"现在，我们都不许碰它了。","kind":"narration","speaker":"旁白"},{"en":"It is being repaired by a friend of my father’s.","zh":"我父亲的一位朋友正在修理它。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l011","number":11,"book":2,"title":"One good turn deserves another","paragraphs":[{"index":0,"rows":[{"en":"I was having dinner at a restaurant when Tony Steele came in.","zh":"我正在一家餐馆吃晚饭时，托尼·斯蒂尔走了进来。","kind":"narration","speaker":"旁白"},{"en":"Tony worked in a lawyer's office years ago, but he is now working at a bank.","zh":"托尼几年前在一家律师事务所工作，但现在在银行上班。","kind":"narration","speaker":"旁白"},{"en":"He gets a good salary, but he always borrows money from his friends and never pays it back.","zh":"他的薪水不错，可他总向朋友借钱，而且从来不还。","kind":"narration","speaker":"旁白"},{"en":"Tony saw me and came and sat at the same table.","zh":"托尼看见了我，走过来，和我坐在同一张桌旁。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He has never borrowed money from me.","zh":"他从来没有向我借过钱。","kind":"narration","speaker":"旁白"},{"en":"While he was eating, I asked him to lend me twenty pounds.","zh":"他吃饭时，我请他借给我二十英镑。","kind":"narration","speaker":"旁白"},{"en":"To my surprise, he gave me the money immediately.","zh":"出乎我的意料，他立刻把钱给了我。","kind":"narration","speaker":"旁白"},{"en":"‘I have never borrowed any money from you,’ Tony said, ‘so now you can pay for my dinner!’","zh":"“我从来没有向你借过钱，”托尼说，“所以现在你可以替我付晚饭钱了！”","kind":"speech","speaker":"托尼","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l012","number":12,"book":2,"title":"Goodbye and good luck","paragraphs":[{"index":0,"rows":[{"en":"Our neighbour, Captain Charles Alison, will sail from Portsmouth tomorrow.","zh":"我们的邻居查尔斯·艾利森船长明天将从朴次茅斯启航。","kind":"narration","speaker":"旁白"},{"en":"We'll meet him at the harbour early in the morning.","zh":"我们将一大早到港口去见他。","kind":"narration","speaker":"旁白"},{"en":"He will be in his small boat, Topsail.","zh":"他会在自己的小船“托普塞尔号”上。","kind":"narration","speaker":"旁白"},{"en":"Topsail is a famous little boat.","zh":"“托普塞尔号”是一艘有名的小船。","kind":"narration","speaker":"旁白"},{"en":"It has sailed across the Atlantic many times.","zh":"它已经多次横渡大西洋。","kind":"narration","speaker":"旁白"},{"en":"Captain Alison will set out at eight o'clock, so we'll have plenty of time.","zh":"艾利森船长将在八点出发，所以我们的时间很充裕。","kind":"narration","speaker":"旁白"},{"en":"We'll see his boat and then we'll say goodbye to him.","zh":"我们将先看看他的船，然后向他道别。","kind":"narration","speaker":"旁白"},{"en":"He will be away for two months.","zh":"他将离开两个月。","kind":"narration","speaker":"旁白"},{"en":"We are very proud of him.","zh":"我们为他感到很自豪。","kind":"narration","speaker":"旁白"},{"en":"He will take part in an important race across the Atlantic.","zh":"他将参加一场重要的横渡大西洋比赛。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l013","number":13,"book":2,"title":"The Greenwood Boys","paragraphs":[{"index":0,"rows":[{"en":"The Greenwood Boys are a group of pop singers.","zh":"“绿林少年”是一个流行歌曲演唱组合。","kind":"narration","speaker":"旁白"},{"en":"At present, they are visiting all parts of the country.","zh":"目前，他们正在全国各地访问演出。","kind":"narration","speaker":"旁白"},{"en":"They will be arriving here tomorrow.","zh":"他们明天就要到这里了。","kind":"narration","speaker":"旁白"},{"en":"They will be coming by train and most of the young people in the town will be meeting them at the station.","zh":"他们将乘火车来，镇上的大多数年轻人将到车站迎接他们。","kind":"narration","speaker":"旁白"},{"en":"Tomorrow evening they will be singing at the Workers’ Club.","zh":"明天晚上，他们将在工人俱乐部演唱。","kind":"narration","speaker":"旁白"},{"en":"The Greenwood Boys will be staying for five days.","zh":"“绿林少年”将停留五天。","kind":"narration","speaker":"旁白"},{"en":"During this time, they will give five performances.","zh":"在此期间，他们将演出五场。","kind":"narration","speaker":"旁白"},{"en":"As usual, the police will have a difficult time.","zh":"照例，警察将会忙得不可开交。","kind":"narration","speaker":"旁白"},{"en":"They will be trying to keep order.","zh":"他们将设法维持秩序。","kind":"narration","speaker":"旁白"},{"en":"It is always the same on these occasions.","zh":"每逢这种场合，情况总是如此。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l014","number":14,"book":2,"title":"Do you speak English?","paragraphs":[{"index":0,"rows":[{"en":"I had an amusing experience last year.","zh":"去年，我有过一次有趣的经历。","kind":"narration","speaker":"旁白"},{"en":"After I had left a small village in the south of France, I drove on to the next town.","zh":"离开法国南部的一个小村庄后，我继续开车前往下一个城镇。","kind":"narration","speaker":"旁白"},{"en":"On the way, a young man waved to me.","zh":"途中，一个年轻人向我招手。","kind":"narration","speaker":"旁白"},{"en":"I stopped and he asked me for a lift.","zh":"我停下车，他请求搭我的车。","kind":"narration","speaker":"旁白"},{"en":"As soon as he had got into the car, I said good morning to him in French and he replied in the same language.","zh":"他一上车，我就用法语向他问早安，他也用同一种语言回答了我。","kind":"narration","speaker":"旁白"},{"en":"Apart from a few words, I do not know any French at all.","zh":"除了几个词以外，我一点法语也不懂。","kind":"narration","speaker":"旁白"},{"en":"Neither of us spoke during the journey.","zh":"一路上，我们谁也没有说话。","kind":"narration","speaker":"旁白"},{"en":"I had nearly reached the town, when the young man suddenly said, very slowly, ‘Do you speak English?’","zh":"快到城镇时，那个年轻人突然十分缓慢地问：“你会说英语吗？”","kind":"mixed","speaker":"旁白与搭车的年轻人","breakBefore":true},{"en":"As I soon learnt, he was English himself!","zh":"我很快就得知，原来他自己就是英国人！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l015","number":15,"book":2,"title":"Good news","paragraphs":[{"index":0,"rows":[{"en":"The secretary told me that Mr. Harmsworth would see me.","zh":"秘书告诉我，哈姆斯沃思先生要见我。","kind":"narration","speaker":"旁白"},{"en":"I felt very nervous when I went into his office.","zh":"走进他的办公室时，我感到非常紧张。","kind":"narration","speaker":"旁白"},{"en":"He did not look up from his desk when I entered.","zh":"我进去时，他没有从办公桌前抬起头。","kind":"narration","speaker":"旁白"},{"en":"After I had sat down, he said that business was very bad.","zh":"我坐下后，他说生意很不景气。","kind":"narration","speaker":"旁白"},{"en":"He told me that the firm could not afford to pay such large salaries.","zh":"他告诉我，公司负担不起这么高的工资。","kind":"narration","speaker":"旁白"},{"en":"Twenty people had already left.","zh":"已经有二十个人离开了。","kind":"narration","speaker":"旁白"},{"en":"I knew that my turn had come.","zh":"我知道，这下轮到我了。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘Mr. Harmsworth,’ I said in a weak voice.","zh":"“哈姆斯沃思先生，”我用微弱的声音说。","kind":"speech","speaker":"我"}]},{"index":2,"rows":[{"en":"‘Don’t interrupt,’ he said.","zh":"“别打断我，”他说。","kind":"speech","speaker":"哈姆斯沃思先生"}]},{"index":3,"rows":[{"en":"Then he smiled and told me I would receive an extra thousand pounds a year!","zh":"接着，他笑了，告诉我每年要给我多加一千英镑！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l016","number":16,"book":2,"title":"A polite request","paragraphs":[{"index":0,"rows":[{"en":"If you park your car in the wrong place, a traffic policeman will soon find it.","zh":"如果你把车停错地方，交通警察很快就会发现它。","kind":"narration","speaker":"旁白"},{"en":"You will be very lucky if he lets you go without a ticket.","zh":"如果他不向你开罚单就让你走，那你可真幸运。","kind":"narration","speaker":"旁白"},{"en":"However, this does not always happen.","zh":"然而，情况并不总是这样。","kind":"narration","speaker":"旁白"},{"en":"Traffic police are sometimes very polite.","zh":"交通警察有时也很客气。","kind":"narration","speaker":"旁白"},{"en":"During a holiday in Sweden, I found this. note on my car: ‘Sir, we welcome you to our city.","zh":"在瑞典度假时，我发现车上有这样一张便条：“先生，欢迎您来到本市。”","kind":"mixed","speaker":"旁白与交警便条","breakBefore":true},{"en":"This is a “No Parking” area.","zh":"“这里是禁止停车区域。”","kind":"note","speaker":"交警便条"},{"en":"You will enjoy your stay here if you pay attention to our street signs.","zh":"“如果您留意我们的街道标志，就会在这里过得愉快。”","kind":"note","speaker":"交警便条"},{"en":"This note is only a reminder.’","zh":"“这张便条只是一个提醒。”","kind":"note","speaker":"交警便条"},{"en":"If you receive a request like this, you cannot fail to obey it!","zh":"如果你收到这样的请求，就一定会照办！","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l017","number":17,"book":2,"title":"Always young","paragraphs":[{"index":0,"rows":[{"en":"My aunt Jennifer is an actress.","zh":"我姑妈詹妮弗是一名演员。","kind":"narration","speaker":"旁白"},{"en":"She must be at least thirty-five years old.","zh":"她想必至少有三十五岁了。","kind":"narration","speaker":"旁白"},{"en":"In spite of this, she often appears on the stage as a young girl.","zh":"尽管如此，她却经常在舞台上扮演少女。","kind":"narration","speaker":"旁白"},{"en":"Jennifer will have to take part in a new play soon.","zh":"詹妮弗不久就得参演一部新戏。","kind":"narration","speaker":"旁白"},{"en":"This time, she will be a girl of seventeen.","zh":"这一次，她将扮演一位十七岁的姑娘。","kind":"narration","speaker":"旁白"},{"en":"In the play, she must appear in a bright red dress and long black stockings.","zh":"在戏中，她必须穿着鲜红的连衣裙和黑色长袜出场。","kind":"narration","speaker":"旁白"},{"en":"Last year in another play, she had to wear short socks and a bright, orange-coloured dress.","zh":"去年在另一部戏里，她得穿短袜和一条鲜艳的橙色连衣裙。","kind":"narration","speaker":"旁白"},{"en":"If anyone ever asks her how old she is, she always answers, ‘Darling, it must be terrible to be grown up!’","zh":"如果有人问起她的年龄，她总是回答：“亲爱的，长大一定是件可怕的事！”","kind":"mixed","speaker":"旁白与詹妮弗","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l018","number":18,"book":2,"title":"He often does this!","paragraphs":[{"index":0,"rows":[{"en":"After I had had lunch at a village pub, I looked for my bag.","zh":"在一家乡村小酒馆吃过午饭后，我开始找我的包。","kind":"narration","speaker":"旁白"},{"en":"I had left it on a chair beside the door and now it wasn’t there!","zh":"我原先把包放在门边的一把椅子上，可现在它不见了！","kind":"narration","speaker":"旁白"},{"en":"As I was looking for it, the landlord came in.","zh":"我正在找包时，店主走了进来。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘Did you have a good meal?’ he asked.","zh":"“饭吃得好吗？”他问。","kind":"speech","speaker":"店主"}]},{"index":2,"rows":[{"en":"‘Yes, thank you,’ I answered, ‘but I can’t pay the bill.","zh":"“很好，谢谢，”我回答，“可是我没法付账了。”","kind":"speech","speaker":"我"},{"en":"I haven’t got my bag.’","zh":"“我的包不见了。”","kind":"speech","speaker":"我"}]},{"index":3,"rows":[{"en":"The landlord smiled and immediately went out.","zh":"店主笑了笑，立刻走了出去。","kind":"narration","speaker":"旁白"},{"en":"In a few minutes he returned with my bag and gave it back to me.","zh":"几分钟后，他拿着我的包回来，把它还给了我。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"‘I'm very sorry,’ he said.","zh":"“实在抱歉，”他说。","kind":"speech","speaker":"店主"},{"en":"‘My dog had taken it into the garden.","zh":"“我的狗把包叼到花园里去了。”","kind":"speech","speaker":"店主"},{"en":"He often does this!’","zh":"“它经常这样！”","kind":"speech","speaker":"店主"}]}]},{"lessonId":"nce-b2-eef57c-l019","number":19,"book":2,"title":"Sold out","paragraphs":[{"index":0,"rows":[{"en":"‘The play may begin at any moment,’ I said.","zh":"“戏随时都可能开演，”我说。","kind":"speech","speaker":"我","breakBefore":true},{"en":"‘It may have begun already,’ Susan answered.","zh":"“说不定已经开演了，”苏珊回答。","kind":"speech","speaker":"苏珊","breakBefore":true},{"en":"I hurried to the ticket office.","zh":"我赶到售票处。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"‘May I have two tickets please?’ I asked.","zh":"“请给我两张票，好吗？”我问。","kind":"speech","speaker":"我","breakBefore":true},{"en":"‘I'm sorry, we’ve sold out,’ the girl said.","zh":"“对不起，票已经卖完了，”售票的姑娘说。","kind":"speech","speaker":"售票员","breakBefore":true},{"en":"‘What a pity!’ Susan exclaimed.","zh":"“真遗憾！”苏珊叫道。","kind":"speech","speaker":"苏珊","breakBefore":true},{"en":"Just then, a man hurried to the ticket office.","zh":"就在这时，一名男子匆忙来到售票处。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"‘Can I return these two tickets?’ he asked.","zh":"“这两张票可以退吗？”他问。","kind":"speech","speaker":"退票男子","breakBefore":true},{"en":"‘Certainly,’ the girl said.","zh":"“当然可以，”售票的姑娘说。","kind":"speech","speaker":"售票员","breakBefore":true},{"en":"I went back to the ticket office at once.","zh":"我立刻又回到售票处。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"‘Could I have those two tickets please?’ I asked.","zh":"“请把那两张票卖给我，好吗？”我问。","kind":"speech","speaker":"我","breakBefore":true},{"en":"‘Certainly,’ the girl said, ‘but they’re for next Wednesday's performance.","zh":"“当然可以，”售票的姑娘说，“不过，这是下星期三那场的票。”","kind":"speech","speaker":"售票员","breakBefore":true},{"en":"Do you still want them?’","zh":"“你还要吗？”","kind":"speech","speaker":"售票员"},{"en":"‘I might as well have them,’ I said sadly.","zh":"“那我还是买下来吧，”我沮丧地说。","kind":"speech","speaker":"我","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l020","number":20,"book":2,"title":"One man in a boat","paragraphs":[{"index":0,"rows":[{"en":"Fishing is my favourite sport.","zh":"钓鱼是我最喜欢的运动。","kind":"narration","speaker":"旁白"},{"en":"I often fish for hours without catching anything.","zh":"我经常钓上几个小时，却什么也钓不到。","kind":"narration","speaker":"旁白"},{"en":"But this does not worry me.","zh":"可这并不让我烦恼。","kind":"narration","speaker":"旁白"},{"en":"Some fishermen are unlucky.","zh":"有些钓鱼的人运气不好。","kind":"narration","speaker":"旁白"},{"en":"Instead of catching fish, they catch old boots and rubbish.","zh":"他们钓到的是旧靴子和垃圾，而不是鱼。","kind":"narration","speaker":"旁白"},{"en":"I am even less lucky.","zh":"我比他们更不走运。","kind":"narration","speaker":"旁白"},{"en":"I never catch anything — not even old boots.","zh":"我从来什么也钓不到，连旧靴子也钓不到。","kind":"narration","speaker":"旁白"},{"en":"After having spent whole mornings on the river, I always go home with an empty bag.","zh":"每次在河上待了整个上午后，我总是提着空袋子回家。","kind":"narration","speaker":"旁白"},{"en":"‘You must give up fishing!’ my friends say.","zh":"“你该放弃钓鱼了！”朋友们说。","kind":"speech","speaker":"朋友们","breakBefore":true},{"en":"‘It’s a waste of time.’","zh":"“这完全是在浪费时间。”","kind":"speech","speaker":"朋友们"},{"en":"But they don’t realize one important thing.","zh":"可他们没有明白一件要紧的事。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"I'm not really interested in fishing.","zh":"我其实对钓鱼并不感兴趣。","kind":"narration","speaker":"旁白"},{"en":"I am only interested in sitting in a boat and doing nothing at all!","zh":"我感兴趣的只是坐在船里，什么事也不干！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l021","number":21,"book":2,"title":"Mad or not?","paragraphs":[{"index":0,"rows":[{"en":"Aeroplanes are slowly driving me mad.","zh":"飞机正在慢慢把我逼疯。","kind":"narration","speaker":"旁白"},{"en":"I live near an airport and passing planes can be heard night and day.","zh":"我住在机场附近，白天黑夜都能听见飞机飞过的声音。","kind":"narration","speaker":"旁白"},{"en":"The airport was built years ago, but for some reason it could not be used then.","zh":"机场多年前就建好了，可当时不知出于什么原因，未能投入使用。","kind":"narration","speaker":"旁白"},{"en":"Last year, however, it came into use.","zh":"不过，它去年投入使用了。","kind":"narration","speaker":"旁白"},{"en":"Over a hundred people must have been driven away from their homes by the noise.","zh":"想必已经有一百多人被噪声逼得离开了家。","kind":"narration","speaker":"旁白"},{"en":"I am one of the few people left.","zh":"我是少数留下来的人之一。","kind":"narration","speaker":"旁白"},{"en":"Sometimes I think this house will be knocked down by a passing plane.","zh":"有时我觉得，这栋房子会被一架飞过的飞机撞倒。","kind":"narration","speaker":"旁白"},{"en":"I have been offered a large sum of money to go away, but I am determined to stay here.","zh":"有人愿意付给我一大笔钱让我搬走，可我决心留在这里。","kind":"narration","speaker":"旁白"},{"en":"Everybody says I must be mad and they are probably right.","zh":"人人都说我一定疯了，他们大概是对的。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l022","number":22,"book":2,"title":"A glass envelope","paragraphs":[{"index":0,"rows":[{"en":"My daughter, Jane, never dreamed of receiving a letter from a girl of her own age in Holland.","zh":"我的女儿简做梦也没想到，会收到荷兰一位同龄姑娘的来信。","kind":"narration","speaker":"旁白"},{"en":"Last year, we were travelling across the Channel and Jane put a piece of paper with her name and address on it into a bottle.","zh":"去年，我们横渡英吉利海峡时，简把一张写有自己姓名和地址的纸放进了一个瓶子里。","kind":"narration","speaker":"旁白"},{"en":"She threw the bottle into the sea.","zh":"她把瓶子扔进了海里。","kind":"narration","speaker":"旁白"},{"en":"She never thought of it again, but ten months later, she received a letter from a girl in Holland.","zh":"此后她再也没想起这件事，可十个月后，她收到了荷兰一位姑娘的来信。","kind":"narration","speaker":"旁白"},{"en":"Both girls write to each other regularly now.","zh":"现在，两个姑娘定期互相写信。","kind":"narration","speaker":"旁白"},{"en":"However, they have decided to use the post office.","zh":"不过，她们已经决定改用邮局寄信了。","kind":"narration","speaker":"旁白"},{"en":"Letters will cost a little more, but they will certainly travel faster.","zh":"这样寄信虽然会多花一点钱，但信件肯定会寄得更快。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l023","number":23,"book":2,"title":"A new house","paragraphs":[{"index":0,"rows":[{"en":"I had a letter from my sister yesterday.","zh":"昨天，我收到了姐姐的一封信。","kind":"narration","speaker":"旁白"},{"en":"She lives in Nigeria.","zh":"她住在尼日利亚。","kind":"narration","speaker":"旁白"},{"en":"In her letter, she said that she would come to England next year.","zh":"她在信里说，明年她要来英国。","kind":"narration","speaker":"旁白"},{"en":"If she comes, she will get a surprise.","zh":"如果她来，一定会大吃一惊。","kind":"narration","speaker":"旁白"},{"en":"We are now living in a beautiful new house in the country.","zh":"我们现在住在乡下一栋漂亮的新房子里。","kind":"narration","speaker":"旁白"},{"en":"Work on it had begun before my sister left.","zh":"在姐姐离开以前，这栋房子就已经动工了。","kind":"narration","speaker":"旁白"},{"en":"The house was completed five months ago.","zh":"房子是五个月前建成的。","kind":"narration","speaker":"旁白"},{"en":"In my letter, I told her that she could stay with us.","zh":"我在信里告诉她，她可以和我们住在一起。","kind":"narration","speaker":"旁白"},{"en":"The house has many large rooms and there is a lovely garden.","zh":"这栋房子有许多宽敞的房间，还有一个可爱的花园。","kind":"narration","speaker":"旁白"},{"en":"It is a very modern house, so it looks strange to some people.","zh":"这是一栋非常现代化的房子，所以在有些人看来，它的样子很奇怪。","kind":"narration","speaker":"旁白"},{"en":"It must be the only modern house in the district.","zh":"它想必是这一带唯一的现代化房屋。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l024","number":24,"book":2,"title":"It could be worse","paragraphs":[{"index":0,"rows":[{"en":"I entered the hotel manager’s office and sat down.","zh":"我走进旅馆经理的办公室，坐了下来。","kind":"narration","speaker":"旁白"},{"en":"I had just lost £50 and I felt very upset.","zh":"我刚丢了五十英镑，心里非常难过。","kind":"narration","speaker":"旁白"},{"en":"‘I left the money in my room,’ I said, ‘and it’s not there now.’","zh":"“我把钱放在房间里，”我说，“可现在钱不见了。”","kind":"speech","speaker":"我","breakBefore":true},{"en":"The manager was sympathetic, but he could do nothing.","zh":"经理很同情我，却无能为力。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"‘Everyone's losing money these days,’ he said.","zh":"“这些日子人人都在丢钱，”他说。","kind":"speech","speaker":"旅馆经理","breakBefore":true},{"en":"He started to complain about this wicked world but was interrupted by a knock at the door.","zh":"他开始抱怨这个邪恶的世界，可一阵敲门声打断了他。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"A girl came in and put an envelope on his desk.","zh":"一个姑娘走进来，把一个信封放在他的办公桌上。","kind":"narration","speaker":"旁白"},{"en":"It contained £50.","zh":"信封里装着五十英镑。","kind":"narration","speaker":"旁白"},{"en":"‘I found this outside this gentleman’s room,’ she said.","zh":"“这是我在这位先生的房门外捡到的，”她说。","kind":"speech","speaker":"姑娘","breakBefore":true},{"en":"‘Well,’ I said to the manager, ‘there is still some honesty in this world!’","zh":"“看来，”我对经理说，“这世上还是有诚实的人啊！”","kind":"speech","speaker":"我","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l025","number":25,"book":2,"title":"Do the English speak English?","paragraphs":[{"index":0,"rows":[{"en":"I arrived in London at last.","zh":"我终于到了伦敦。","kind":"narration","speaker":"旁白"},{"en":"The railway station was big, black and dark.","zh":"火车站很大，又黑又暗。","kind":"narration","speaker":"旁白"},{"en":"I did not know the way to my hotel, so I asked a porter.","zh":"我不知道去旅馆的路，所以向一名搬运工打听。","kind":"narration","speaker":"旁白"},{"en":"I not only spoke English very carefully, but very clearly as well.","zh":"我说英语时不仅十分仔细，而且说得很清楚。","kind":"narration","speaker":"旁白"},{"en":"The porter, however, could not understand me.","zh":"然而，搬运工听不懂我的话。","kind":"narration","speaker":"旁白"},{"en":"I repeated my question several times and at last he understood.","zh":"我把问题重复了好几遍，他最后才听懂。","kind":"narration","speaker":"旁白"},{"en":"He answered me, but he spoke neither slowly nor clearly.","zh":"他回答了我，可他说得既不慢，也不清楚。","kind":"narration","speaker":"旁白"},{"en":"‘I am a foreigner,’ I said.","zh":"“我是外国人，”我说。","kind":"speech","speaker":"我","breakBefore":true},{"en":"Then he spoke slowly, but I could not understand him.","zh":"于是，他放慢了语速，可我还是听不懂他的话。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"My teacher never spoke English like that!","zh":"我的老师从来不这样说英语！","kind":"narration","speaker":"旁白"},{"en":"The porter and I looked at each other and smiled.","zh":"搬运工和我相视而笑。","kind":"narration","speaker":"旁白"},{"en":"Then he said something and I understood it.","zh":"接着，他又说了一句话，这回我听懂了。","kind":"narration","speaker":"旁白"},{"en":"‘You’ll soon learn English!’ he said.","zh":"“你很快就能学会英语的！”他说。","kind":"speech","speaker":"搬运工","breakBefore":true},{"en":"I wonder.","zh":"我对此很怀疑。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"In England, each person speaks a different language.","zh":"在英国，每个人都说着不同的语言。","kind":"narration","speaker":"旁白"},{"en":"The English understand each other, but I don’t understand them!","zh":"英国人彼此听得懂，可我听不懂他们的话！","kind":"narration","speaker":"旁白"},{"en":"Do they speak English?","zh":"他们说的是英语吗？","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l026","number":26,"book":2,"title":"The best art critics","paragraphs":[{"index":0,"rows":[{"en":"I am an art student and I paint a lot of pictures.","zh":"我是学美术的，画了许多画。","kind":"narration","speaker":"旁白"},{"en":"Many people pretend that they understand modern art.","zh":"许多人装作懂现代艺术。","kind":"narration","speaker":"旁白"},{"en":"They always tell you what a picture is ‘about’.","zh":"他们总爱告诉你一幅画“讲的是”什么。","kind":"narration","speaker":"旁白"},{"en":"Of course, many pictures are not ‘about’ anything.","zh":"当然，许多画根本不“讲”任何东西。","kind":"narration","speaker":"旁白"},{"en":"They are just pretty patterns.","zh":"它们只是些好看的图案。","kind":"narration","speaker":"旁白"},{"en":"We like them in the same way that we like pretty curtain material.","zh":"我们喜欢这些画，就像喜欢漂亮的窗帘布一样。","kind":"narration","speaker":"旁白"},{"en":"I think that young children often appreciate modern pictures better than anyone else.","zh":"我认为，小孩子往往比任何人都更能欣赏现代绘画。","kind":"narration","speaker":"旁白"},{"en":"They notice more.","zh":"他们观察到的东西更多。","kind":"narration","speaker":"旁白"},{"en":"My sister is only seven, but she always tells me whether my pictures are good or not.","zh":"我妹妹只有七岁，可她总能告诉我，我的画好不好。","kind":"narration","speaker":"旁白"},{"en":"She came into my room yesterday.","zh":"昨天，她走进了我的房间。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘What are you doing?’ she asked.","zh":"“你在干什么？”她问。","kind":"speech","speaker":"妹妹"}]},{"index":2,"rows":[{"en":"‘I'm hanging this picture on the wall,’ I answered.","zh":"“我在把这幅画挂到墙上，”我回答。","kind":"speech","speaker":"我"},{"en":"‘It’s a new one.","zh":"“这是一幅新画。”","kind":"speech","speaker":"我"},{"en":"Do you like it?’","zh":"“你喜欢它吗？”","kind":"speech","speaker":"我"}]},{"index":3,"rows":[{"en":"She looked at it critically for a moment.","zh":"她用挑剔的眼光看了一会儿。","kind":"narration","speaker":"旁白"},{"en":"‘It’s all right,’ she said, ‘but isn’t it upside down?’","zh":"“还行，”她说，“可它是不是挂倒了？”","kind":"speech","speaker":"妹妹","breakBefore":true}]},{"index":4,"rows":[{"en":"I looked at it again.","zh":"我又看了一眼。","kind":"narration","speaker":"旁白"},{"en":"She was right!","zh":"她说得对！","kind":"narration","speaker":"旁白"},{"en":"It was!","zh":"画真的挂倒了！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l027","number":27,"book":2,"title":"A wet night","paragraphs":[{"index":0,"rows":[{"en":"Late in the afternoon, the boys put up their tent in the middle of a field.","zh":"快到傍晚时，男孩子们在田野中央搭起了帐篷。","kind":"narration","speaker":"旁白"},{"en":"As soon as this was done, they cooked a meal over an open fire.","zh":"帐篷一搭好，他们就在露天生火做饭。","kind":"narration","speaker":"旁白"},{"en":"They were all hungry and the food smelled good.","zh":"他们都饿了，饭菜闻起来也很香。","kind":"narration","speaker":"旁白"},{"en":"After a wonderful meal, they told stories and sang songs by the campfire.","zh":"美美地吃了一顿后，他们围着篝火讲故事、唱歌。","kind":"narration","speaker":"旁白"},{"en":"But some time later it began to rain.","zh":"可是过了一会儿，天开始下雨了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The boys felt tired so they put out the fire and crept into their tent.","zh":"男孩子们感到累了，于是熄灭了火，钻进了帐篷。","kind":"narration","speaker":"旁白"},{"en":"Their sleeping bags were warm and comfortable, so they all slept soundly.","zh":"他们的睡袋暖和又舒服，因此大家都睡得很沉。","kind":"narration","speaker":"旁白"},{"en":"In the middle of the night, two boys woke up and began shouting.","zh":"半夜，两个男孩子醒来，开始大喊。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The tent was full of water!","zh":"帐篷里全是水！","kind":"narration","speaker":"旁白"},{"en":"They all leapt out of their sleeping bags and hurried outside.","zh":"他们都从睡袋里跳出来，急忙跑到外面。","kind":"narration","speaker":"旁白"},{"en":"It was raining heavily and they found that a stream had formed in the field.","zh":"雨下得很大，他们发现田野里已经形成了一条小溪。","kind":"narration","speaker":"旁白"},{"en":"The stream wound its way across the field and then flowed right under their tent!","zh":"小溪蜿蜒穿过田野，随后正好从他们的帐篷底下流过！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l028","number":28,"book":2,"title":"No parking","paragraphs":[{"index":0,"rows":[{"en":"Jasper White is one of those rare people who believes in ancient myths.","zh":"贾斯珀·怀特是那些为数不多的相信古老神话的人之一。","kind":"narration","speaker":"旁白"},{"en":"He has just bought a new house in the city, but ever since he moved in, he has had trouble with cars and their owners.","zh":"他刚在城里买了一栋新房子，可自从搬进来，就一直受到汽车和车主的困扰。","kind":"narration","speaker":"旁白"},{"en":"When he returns home at night, he always finds that someone has parked a car outside his gate.","zh":"每当他晚上回家，总会发现有人把车停在他家大门外。","kind":"narration","speaker":"旁白"},{"en":"Because of this, he has not been able to get his own car into his garage even once.","zh":"正因为如此，他自己的车竟一次也没能开进车库。","kind":"narration","speaker":"旁白"},{"en":"Jasper has put up ‘No Parking’ signs outside his gate, but these have not had any effect.","zh":"贾斯珀在大门外竖起了“禁止停车”的牌子，可这些牌子毫无效果。","kind":"narration","speaker":"旁白"},{"en":"Now he has put an ugly stone head over the gate.","zh":"现在，他在大门上方安了一个丑陋的石头像。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It is one of the ugliest faces I have ever seen.","zh":"那是我见过的最丑陋的面孔之一。","kind":"narration","speaker":"旁白"},{"en":"I asked him what it was and he told me that it was Medusa, the Gorgon.","zh":"我问他那是什么，他告诉我，那是蛇发女妖美杜莎。","kind":"narration","speaker":"旁白"},{"en":"Jasper hopes that she will turn cars and their owners to stone.","zh":"贾斯珀希望她能把汽车和车主都变成石头。","kind":"narration","speaker":"旁白"},{"en":"But none of them has been turned to stone yet!","zh":"可是到现在，汽车和车主一个也没有变成石头！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l029","number":29,"book":2,"title":"Taxi!","paragraphs":[{"index":0,"rows":[{"en":"Captain Ben Fawcett has bought an unusual taxi and has begun a new service.","zh":"本·福西特机长买下了一辆不同寻常的出租车，并且开办了一项新服务。","kind":"narration","speaker":"旁白"},{"en":"The ‘taxi’ is a small Swiss aeroplane called a ‘Pilatus Porter’.","zh":"这辆“出租车”是一架瑞士制造的小飞机，名叫“皮拉图斯·波特”。","kind":"narration","speaker":"旁白"},{"en":"This wonderful plane can carry seven passengers.","zh":"这架出色的飞机能载七名乘客。","kind":"narration","speaker":"旁白"},{"en":"The most surprising thing about it, however, is that it can land anywhere: on snow, water, or even on a ploughed field.","zh":"不过，最令人惊奇的是，它能在任何地方降落：雪地、水面，甚至犁过的田地。","kind":"narration","speaker":"旁白"},{"en":"Captain Fawcett’s first passenger was a doctor who flew from Birmingham to a lonely village in the Welsh mountains.","zh":"福西特机长的第一位乘客是一位医生，他从伯明翰飞往威尔士山区一个偏僻的村庄。","kind":"narration","speaker":"旁白"},{"en":"Since then, Captain Fawcett has flown passengers to many unusual places.","zh":"从那以后，福西特机长载着乘客去过许多不寻常的地方。","kind":"narration","speaker":"旁白"},{"en":"Once he landed on the roof of a block of flats and on another occasion, he landed in a deserted car park.","zh":"他曾降落在一栋公寓楼的楼顶上，另一次则降落在一个空无一人的停车场。","kind":"narration","speaker":"旁白"},{"en":"Captain Fawcett has just refused a strange request from a businessman.","zh":"福西特机长刚刚拒绝了一位商人的奇怪请求。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The man wanted to fly to Rockall, a lonely island in the Atlantic Ocean, but Captain Fawcett did not take him because the trip was too dangerous.","zh":"那人想飞往大西洋中的孤岛罗科尔岛，可福西特机长没有送他去，因为这趟行程太危险了。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l030","number":30,"book":2,"title":"Football or polo?","paragraphs":[{"index":0,"rows":[{"en":"The Wayle is a small river that cuts across the park near my home.","zh":"韦尔河是一条小河，穿过我家附近的公园。","kind":"narration","speaker":"旁白"},{"en":"I like sitting by the Wayle on fine afternoons.","zh":"天气晴朗的下午，我喜欢坐在韦尔河边。","kind":"narration","speaker":"旁白"},{"en":"It was warm last Sunday, so I went and sat on the river bank as usual.","zh":"上星期天天气暖和，所以我照常去河岸边坐了坐。","kind":"narration","speaker":"旁白"},{"en":"Some children were playing games on the bank and there were some people rowing on the river.","zh":"一些孩子在岸上做游戏，河里也有一些人在划船。","kind":"narration","speaker":"旁白"},{"en":"Suddenly, one of the children kicked a ball very hard and it went towards a passing boat.","zh":"突然，一个孩子使劲踢了一脚球，球朝一艘经过的小船飞去。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Some people on the bank called out to the man in the boat, but he did not hear them.","zh":"岸上的一些人向船上的男子大喊，可他没有听见。","kind":"narration","speaker":"旁白"},{"en":"The ball struck him so hard that he nearly fell into the water.","zh":"球重重地砸到他身上，他差点掉进水里。","kind":"narration","speaker":"旁白"},{"en":"I turned to look at the children, but there weren't any in sight: they had all run away!","zh":"我转头去看那些孩子，可一个也看不见了：他们全都跑了！","kind":"narration","speaker":"旁白"},{"en":"The man laughed when he realized what had happened.","zh":"那个男子明白发生了什么事以后，笑了起来。","kind":"narration","speaker":"旁白"},{"en":"He called out to the children and threw the ball back to the bank.","zh":"他朝孩子们喊了一声，把球扔回了岸上。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l031","number":31,"book":2,"title":"Success story","paragraphs":[{"index":0,"rows":[{"en":"Yesterday afternoon Frank Hawkins was telling me about his experiences as a young man.","zh":"昨天下午，弗兰克·霍金斯正在向我讲述他年轻时的经历。","kind":"narration","speaker":"旁白"},{"en":"Before he retired, Frank was the head of a very large business company, but as a boy he used to work in a small shop.","zh":"退休以前，弗兰克是一家大型商业公司的负责人，可在少年时代，他曾在一家小店里工作。","kind":"narration","speaker":"旁白"},{"en":"It was his job to repair bicycles and at that time he used to work fourteen hours a day.","zh":"他的工作是修理自行车，那时他每天要工作十四个小时。","kind":"narration","speaker":"旁白"},{"en":"He saved money for years and in 1958, he bought a small workshop of his own.","zh":"他攒了多年的钱，并在一九五八年买下了一间属于自己的小作坊。","kind":"narration","speaker":"旁白"},{"en":"In his twenties Frank used to make spare parts for aeroplanes.","zh":"弗兰克二十多岁时，曾经制造飞机零配件。","kind":"narration","speaker":"旁白"},{"en":"At that time he had two helpers.","zh":"那时，他有两个帮手。","kind":"narration","speaker":"旁白"},{"en":"In a few years the small workshop had become a large factory which employed seven hundred and twenty-eight people.","zh":"几年以后，小作坊就变成了一家雇有七百二十八人的大工厂。","kind":"narration","speaker":"旁白"},{"en":"Frank smiled when he remembered his hard early years and the long road to success.","zh":"回想起早年的艰苦岁月和漫长的成功之路，弗兰克笑了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He was still smiling when the door opened and his wife came in.","zh":"门开了，他妻子走进来时，他还在笑。","kind":"narration","speaker":"旁白"},{"en":"She wanted him to repair their grandson’s bicycle!","zh":"她想让他修理他们孙子的自行车！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l032","number":32,"book":2,"title":"Shopping made easy","paragraphs":[{"index":0,"rows":[{"en":"People are not so honest as they once were.","zh":"人们不像过去那么诚实了。","kind":"narration","speaker":"旁白"},{"en":"The temptation to steal is greater than ever before — especially in large shops.","zh":"偷窃的诱惑比以往任何时候都大，尤其是在大商店里。","kind":"narration","speaker":"旁白"},{"en":"A detective recently watched a well-dressed woman who always went into a large store on Monday mornings.","zh":"最近，一名侦探监视了一位衣着讲究的妇女，她总在星期一上午走进一家大商店。","kind":"narration","speaker":"旁白"},{"en":"One Monday, there were fewer people in the shop than usual when the woman came in, so it was easier for the detective to watch her.","zh":"一个星期一，这位妇女进店时，店里的顾客比平时少，因此侦探更容易监视她。","kind":"narration","speaker":"旁白"},{"en":"The woman first bought a few small articles.","zh":"这位妇女先买了几件小东西。","kind":"narration","speaker":"旁白"},{"en":"After a little time, she chose one of the most expensive dresses in the shop and handed it to an assistant who wrapped it up for her as quickly as possible.","zh":"过了一会儿，她挑了店里最贵的连衣裙中的一件，交给一名售货员，售货员以最快的速度替她包好。","kind":"narration","speaker":"旁白"},{"en":"Then the woman simply took the parcel and walked out of the shop without paying.","zh":"接着，这位妇女就拿起包裹，连钱都没付就走出了商店。","kind":"narration","speaker":"旁白"},{"en":"When she was arrested, the detective found out that the shop assistant was her daughter.","zh":"她被捕后，侦探发现，那名售货员是她的女儿。","kind":"narration","speaker":"旁白"},{"en":"The girl ‘gave’ her mother a free dress once a week!","zh":"这个姑娘每星期都免费“送”她母亲一件连衣裙！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l033","number":33,"book":2,"title":"Out of the darkness","paragraphs":[{"index":0,"rows":[{"en":"Nearly a week passed before the girl was able to explain what had happened to her.","zh":"将近一个星期过去后，这个姑娘才说得清自己遭遇了什么。","kind":"narration","speaker":"旁白"},{"en":"One afternoon she set out from the coast in a small boat and was caught in a storm.","zh":"一天下午，她驾着一艘小船从海岸出发，遇上了风暴。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Towards evening, the boat struck a rock and the girl jumped into the sea.","zh":"傍晚时，小船撞上一块礁石，姑娘跳进了海里。","kind":"narration","speaker":"旁白"},{"en":"Then she swam to the shore after spending the whole night in the water.","zh":"她在水里度过了整整一夜，随后才游到岸边。","kind":"narration","speaker":"旁白"},{"en":"During that time she covered a distance of eight miles.","zh":"在那段时间里，她游了八英里。","kind":"narration","speaker":"旁白"},{"en":"Early next morning, she saw a light ahead.","zh":"第二天清晨，她看见前方有灯光。","kind":"narration","speaker":"旁白"},{"en":"She knew she was near the shore because the light was high up on the cliffs.","zh":"她知道自己已靠近海岸，因为灯光高高地亮在悬崖上。","kind":"narration","speaker":"旁白"},{"en":"On arriving at the shore, the girl struggled up the cliff towards the light she had seen.","zh":"一到岸边，姑娘就挣扎着爬上悬崖，朝她先前看到的灯光爬去。","kind":"narration","speaker":"旁白"},{"en":"That was all she remembered.","zh":"她能记起的只有这些。","kind":"narration","speaker":"旁白"},{"en":"When she woke up a day later, she found herself in hospital.","zh":"一天后醒来时，她发现自己在医院里。","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l034","number":34,"book":2,"title":"Quick work","paragraphs":[{"index":0,"rows":[{"en":"Dan Robinson has been worried all week.","zh":"丹·鲁宾逊整个星期都很担心。","kind":"narration","speaker":"旁白"},{"en":"Last Tuesday he received a letter from the local police.","zh":"上星期二，他收到了当地警察的一封信。","kind":"narration","speaker":"旁白"},{"en":"In the letter he was asked to call at the station.","zh":"信里请他到警察局去一趟。","kind":"narration","speaker":"旁白"},{"en":"Dan wondered why he was wanted by the police, but he went to the station yesterday and now he is not worried anymore.","zh":"丹不明白警察为什么找他，但他昨天还是去了警察局，现在已经不再担心了。","kind":"narration","speaker":"旁白"},{"en":"At the station, he was told by a smiling policeman that his bicycle had been found.","zh":"在警察局，一位面带微笑的警察告诉他，他的自行车找到了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Five days ago, the policeman told him, the bicycle was picked up in a small village four hundred miles away.","zh":"警察告诉他，五天前，有人在四百英里以外的一个小村庄里发现了那辆自行车。","kind":"narration","speaker":"旁白"},{"en":"It is now being sent to his home by train.","zh":"现在，这辆自行车正由火车运往他家。","kind":"narration","speaker":"旁白"},{"en":"Dan was most surprised when he heard the news.","zh":"丹听到这个消息时，非常吃惊。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He was amused too, because he never expected the bicycle to be found.","zh":"他同时又觉得好笑，因为他从没指望还能找到这辆自行车。","kind":"narration","speaker":"旁白"},{"en":"It was stolen twenty years ago when Dan was a boy of fifteen!","zh":"那辆车是二十年前被偷的，当时丹还是个十五岁的男孩子！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l035","number":35,"book":2,"title":"Stop thief!","paragraphs":[{"index":0,"rows":[{"en":"Roy Trenton used to drive a taxi.","zh":"罗伊·特伦顿过去开出租车。","kind":"narration","speaker":"旁白"},{"en":"A short while ago, however, he became a bus driver and he has not regretted it.","zh":"不过，不久前他当上了公共汽车司机，而且一直没有后悔。","kind":"narration","speaker":"旁白"},{"en":"He is finding his new work far more exciting.","zh":"他觉得自己的新工作刺激得多。","kind":"narration","speaker":"旁白"},{"en":"When he was driving along Catford Street recently, he saw two thieves rush out of a shop and run towards a waiting car.","zh":"最近，他沿着卡特福德街开车时，看见两个窃贼从一家商店冲出来，朝一辆等在那里的汽车跑去。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"One of them was carrying a bag full of money.","zh":"其中一个人提着一只装满钱的袋子。","kind":"narration","speaker":"旁白"},{"en":"Roy acted quickly and drove the bus straight at the thieves.","zh":"罗伊迅速采取行动，开着公共汽车直冲窃贼而去。","kind":"narration","speaker":"旁白"},{"en":"The one with the money got such a fright that he dropped the bag.","zh":"那个提钱的人吓得把袋子都掉了。","kind":"narration","speaker":"旁白"},{"en":"As the thieves were trying to get away in their car, Roy drove his bus into the back of it.","zh":"窃贼正想开车逃走时，罗伊开着公共汽车撞上了他们汽车的尾部。","kind":"narration","speaker":"旁白"},{"en":"While the battered car was moving away, Roy stopped his bus and telephoned the police.","zh":"那辆被撞坏的汽车开走时，罗伊停下公共汽车，打电话报了警。","kind":"narration","speaker":"旁白"},{"en":"The thieves’ car was badly damaged and easy to recognize.","zh":"窃贼的汽车损坏严重，很容易辨认。","kind":"narration","speaker":"旁白"},{"en":"Shortly afterwards, the police stopped the car and both men were arrested.","zh":"不久，警察拦住了那辆汽车，两个人都被捕了。","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l036","number":36,"book":2,"title":"Across the Channel","paragraphs":[{"index":0,"rows":[{"en":"Debbie Hart is going to swim across the English Channel tomorrow.","zh":"黛比·哈特明天打算游过英吉利海峡。","kind":"narration","speaker":"旁白"},{"en":"She is going to set out from the French coast at five o'clock in the morning.","zh":"她计划早晨五点从法国海岸出发。","kind":"narration","speaker":"旁白"},{"en":"Debbie is only eleven years old and she hopes to set up a new world record.","zh":"黛比只有十一岁，她希望创造一项新的世界纪录。","kind":"narration","speaker":"旁白"},{"en":"She is a strong swimmer and many people feel that she is sure to succeed.","zh":"她是一位游泳健将，许多人认为她一定会成功。","kind":"narration","speaker":"旁白"},{"en":"Debbie's father will set out with her in a small boat.","zh":"黛比的父亲将驾着一艘小船陪她一同出发。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Mr. Hart has trained his daughter for years.","zh":"哈特先生多年来一直在训练自己的女儿。","kind":"narration","speaker":"旁白"},{"en":"Tomorrow he will be watching her anxiously as she swims the long distance to England.","zh":"明天，当她长距离游向英国时，他会焦急地注视着她。","kind":"narration","speaker":"旁白"},{"en":"Debbie intends to take short rests every two hours.","zh":"黛比打算每隔两小时短暂休息一次。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"She will have something to drink but she will not eat any solid food.","zh":"她会喝些东西，但不会吃任何固体食物。","kind":"narration","speaker":"旁白"},{"en":"Most of Debbie’s school friends will be waiting for her on the English coast.","zh":"黛比的大多数同学将会在英国海岸等她。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Among them will be Debbie’s mother, who swam the Channel herself when she was a girl.","zh":"等候的人中还有黛比的母亲，她在少女时代也曾亲自游过英吉利海峡。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l037","number":37,"book":2,"title":"The Olympic Games","paragraphs":[{"index":0,"rows":[{"en":"The Olympic Games will be held in our country in four years’ time.","zh":"四年以后，奥林匹克运动会将在我国举行。","kind":"narration","speaker":"旁白"},{"en":"As a great many people will be visiting the country, the government will be building new hotels, an immense stadium, and a new Olympic-standard swimming pool.","zh":"由于将有大批游客来到我国，政府将兴建新的旅馆、一座巨大的体育场，以及一座符合奥运标准的新游泳池。","kind":"narration","speaker":"旁白"},{"en":"They will also be building new roads and a special railway line.","zh":"政府还将修建新的道路和一条专用铁路线。","kind":"narration","speaker":"旁白"},{"en":"The Games will be held just outside the capital and the whole area will be called ‘Olympic City’.","zh":"运动会将在首都近郊举行，整个地区将被称为“奥运城”。","kind":"narration","speaker":"旁白"},{"en":"Workers will have completed the new roads by the end of this year.","zh":"到今年年底，工人们将修好这些新道路。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"By the end of next year, they will have finished work on the new stadium.","zh":"到明年年底，他们将完成新体育场的建设。","kind":"narration","speaker":"旁白"},{"en":"The fantastic modern buildings have been designed by Kurt Gunter.","zh":"这些出色的现代建筑已经由库尔特·冈特设计完成。","kind":"narration","speaker":"旁白"},{"en":"Everybody will be watching anxiously as the new buildings go up.","zh":"随着新建筑一座座拔地而起，人人都会满怀期待地关注着。","kind":"narration","speaker":"旁白"},{"en":"We are all very excited and are looking forward to the Olympic Games because they have never been held before in this country.","zh":"我们都十分兴奋，盼望着奥运会，因为我国以前从未举办过奥运会。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l038","number":38,"book":2,"title":"Everything except the weather","paragraphs":[{"index":0,"rows":[{"en":"My old friend, Harrison, had lived in the Mediterranean for many years before he returned to England.","zh":"我的老朋友哈里森回到英国以前，已经在地中海地区住了许多年。","kind":"narration","speaker":"旁白"},{"en":"He had often dreamed of retiring in England and had planned to settle down in the country.","zh":"他常常梦想在英国退休，并计划在乡下定居。","kind":"narration","speaker":"旁白"},{"en":"He had no sooner returned than he bought a house and went to live there.","zh":"他一回到英国，就买了一栋房子，住了进去。","kind":"narration","speaker":"旁白"},{"en":"Almost immediately he began to complain about the weather, for even though it was still summer, it rained continually and it was often bitterly cold.","zh":"他几乎立刻就开始抱怨天气，因为虽然还是夏天，却不停地下雨，而且常常冷得刺骨。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"After so many years of sunshine, Harrison got a shock.","zh":"享受了那么多年的阳光以后，哈里森对这样的天气大感意外。","kind":"narration","speaker":"旁白"},{"en":"He acted as if he had never lived in England before.","zh":"他的举止仿佛自己从前从未在英国住过一样。","kind":"narration","speaker":"旁白"},{"en":"In the end, it was more than he could bear.","zh":"到最后，这种天气实在让他无法忍受了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He had hardly had time to settle down when he sold the house and left the country.","zh":"他几乎还没来得及安顿下来，就卖掉房子，离开了英国。","kind":"narration","speaker":"旁白"},{"en":"The dream he had had for so many years ended there.","zh":"他多年来的梦想就此结束了。","kind":"narration","speaker":"旁白"},{"en":"Harrison had thought of everything except the weather.","zh":"哈里森什么都考虑到了，唯独漏了天气。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l039","number":39,"book":2,"title":"Am I all right?","paragraphs":[{"index":0,"rows":[{"en":"While John Gilbert was in hospital, he asked his doctor to tell him whether his operation had been successful, but the doctor refused to do so.","zh":"约翰·吉尔伯特住院时，请医生告诉他手术是否成功，医生却拒绝回答。","kind":"narration","speaker":"旁白"},{"en":"The following day, the patient asked for a bedside telephone.","zh":"第二天，这位病人要了一部床头电话。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"When he was alone, he telephoned the hospital exchange and asked for Doctor Millington.","zh":"独自一人时，他拨通了医院总机，要求转接米林顿医生。","kind":"narration","speaker":"旁白"},{"en":"When the doctor answered the phone, Mr. Gilbert said he was inquiring about a certain patient, a Mr. John Gilbert.","zh":"医生接电话后，吉尔伯特先生说，他想打听一位名叫约翰·吉尔伯特的病人的情况。","kind":"narration","speaker":"旁白"},{"en":"He asked if Mr. Gilbert's operation had been successful and the doctor told him that it had been.","zh":"他问吉尔伯特先生的手术是否成功，医生告诉他手术成功了。","kind":"narration","speaker":"旁白"},{"en":"He then asked when Mr. Gilbert would be allowed to go home and the doctor told him that he would have to stay in hosptial for another two weeks.","zh":"接着，他问吉尔伯特先生什么时候可以回家，医生告诉他，还必须在医院住两个星期。","kind":"narration","speaker":"旁白"},{"en":"Then Dr. Millington asked the caller if he was a relative of the patient.","zh":"随后，米林顿医生问来电者是不是病人的亲属。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"‘No,’ the patient answered, ‘I am Mr. John Gilbert.’","zh":"“不是，”病人回答，“我就是约翰·吉尔伯特先生。”","kind":"speech","speaker":"约翰·吉尔伯特","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l040","number":40,"book":2,"title":"Food and talk","paragraphs":[{"index":0,"rows":[{"en":"Last week at a dinner party, the hostess asked me to sit next to Mrs. Rumbold.","zh":"上周参加一次晚宴时，女主人请我坐在兰博尔德太太身旁。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Rumbold was a large, unsmiling lady in a tight black dress.","zh":"兰博尔德太太体态丰腴，脸上毫无笑容，穿着一条紧身黑色连衣裙。","kind":"narration","speaker":"旁白"},{"en":"She did not even look up when I took my seat beside her.","zh":"我在她身旁坐下时，她连头也没抬。","kind":"narration","speaker":"旁白"},{"en":"Her eyes were fixed on her plate and in a short time, she was busy eating.","zh":"她的眼睛一直盯着自己的盘子，不一会儿就忙着吃了起来。","kind":"narration","speaker":"旁白"},{"en":"I tried to make conversation.","zh":"我试着找话聊。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘A new play is coming to “The Globe” soon,’ I said.","zh":"“环球剧院很快就要上演一出新戏了，”我说。","kind":"speech","speaker":"我"},{"en":"‘Will you be seeing it?’","zh":"“您会去看吗？”","kind":"speech","speaker":"我"}]},{"index":2,"rows":[{"en":"‘No,’ she answered.","zh":"“不会，”她回答。","kind":"speech","speaker":"兰博尔德太太"}]},{"index":3,"rows":[{"en":"‘Will you be spending your holidays abroad this year?’ I asked.","zh":"“您今年打算出国度假吗？”我问。","kind":"speech","speaker":"我"}]},{"index":4,"rows":[{"en":"‘No,’ she answered.","zh":"“不打算，”她回答。","kind":"speech","speaker":"兰博尔德太太"}]},{"index":5,"rows":[{"en":"‘Will you be staying in England?’ I asked.","zh":"“您会留在英国吗？”我问。","kind":"speech","speaker":"我"}]},{"index":6,"rows":[{"en":"‘No,’ she answered.","zh":"“不会，”她回答。","kind":"speech","speaker":"兰博尔德太太"}]},{"index":7,"rows":[{"en":"In despair, I asked her whether she was enjoying her dinner.","zh":"我实在没办法了，便问她这顿饭吃得是否愉快。","kind":"narration","speaker":"旁白"}]},{"index":8,"rows":[{"en":"‘Young man,’ she answered, ‘if you ate more and talked less, we would both enjoy our dinner!’","zh":"“年轻人，”她回答，“如果你多吃一点、少说一点，我们两个都会吃得愉快！”","kind":"speech","speaker":"兰博尔德太太"}]}]},{"lessonId":"nce-b2-eef57c-l041","number":41,"book":2,"title":"Do you call that a hat?","paragraphs":[{"index":0,"rows":[{"en":"‘Do you call that a hat?’ I said to my wife.","zh":"“你管那叫帽子？”我对妻子说。","kind":"speech","speaker":"我"}]},{"index":1,"rows":[{"en":"‘You needn’t be so rude about it,’ my wife answered as she looked at herself in the mirror.","zh":"“你用不着说得这么难听，”妻子一边照镜子一边回答。","kind":"speech","speaker":"妻子"}]},{"index":2,"rows":[{"en":"I sat down on one of those modern chairs with holes in it and waited.","zh":"我在一把带孔的现代式椅子上坐下来等着。","kind":"narration","speaker":"旁白"},{"en":"We had been in the hat shop for half an hour and my wife was still in front of the mirror.","zh":"我们已经在帽子店里待了半个小时，妻子还站在镜子前。","kind":"narration","speaker":"旁白"}]},{"index":3,"rows":[{"en":"‘We musn’t buy things we don’t need,’ I remarked suddenly.","zh":"“我们可不能买不需要的东西，”我突然说。","kind":"speech","speaker":"我"},{"en":"I regretted saying it almost at once.","zh":"我几乎立刻就后悔说了这话。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"‘You needn't have said that,’ my wife answered.","zh":"“你这话完全多余，”妻子回答。","kind":"speech","speaker":"妻子"},{"en":"‘I needn’t remind you of that terrible tie you bought yesterday.’","zh":"“不用我提醒你昨天买的那条难看的领带吧。”","kind":"speech","speaker":"妻子"}]},{"index":5,"rows":[{"en":"‘I find it beautiful,’ I said.","zh":"“我觉得它很好看，”我说。","kind":"speech","speaker":"我"},{"en":"‘A man can never have too many ties.’","zh":"“男人的领带再多也不嫌多。”","kind":"speech","speaker":"我"}]},{"index":6,"rows":[{"en":"‘And a woman can’t have too many hats,’ she answered.","zh":"“女人的帽子也是再多都不嫌多，”她回答。","kind":"speech","speaker":"妻子"}]},{"index":7,"rows":[{"en":"Ten minutes later we walked out of the shop together.","zh":"十分钟后，我们一起走出了商店。","kind":"narration","speaker":"旁白"},{"en":"My wife was wearing a hat that looked like a lighthouse!","zh":"妻子头上戴着一顶看起来像灯塔的帽子！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l042","number":42,"book":2,"title":"Not very musical","paragraphs":[{"index":0,"rows":[{"en":"As we had had a long walk through one of the markets of Old Delhi, we stopped at a square to have a rest.","zh":"我们在老德里的一个集市里走了很长一段路，于是停在一处广场上休息。","kind":"narration","speaker":"旁白"},{"en":"After a time, we noticed a snake charmer with two large baskets at the other side of the square, so we went to have a look at him.","zh":"过了一会儿，我们注意到广场另一边有位带着两个大篮子的弄蛇人，便走过去看看。","kind":"narration","speaker":"旁白"},{"en":"As soon as he saw us, he picked up a long pipe which was covered with coins and opened one of the baskets.","zh":"他一看到我们，就拿起一支镶满硬币的长笛，打开了其中一个篮子。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"When he began to play a tune, we had our first glimpse of the snake.","zh":"当他开始吹奏一支曲子时，我们才第一次看到了那条蛇。","kind":"narration","speaker":"旁白"},{"en":"It rose out of the basket and began to follow the movements of the pipe.","zh":"蛇从篮子里昂起身，开始随着笛子的摆动而移动。","kind":"narration","speaker":"旁白"},{"en":"We were very much surprised when the snake charmer suddenly began to play jazz and modern pop songs.","zh":"弄蛇人突然开始吹爵士乐和现代流行歌曲，让我们十分惊讶。","kind":"narration","speaker":"旁白"},{"en":"The snake, however, continued to ‘dance’ slowly.","zh":"然而，那条蛇仍旧慢悠悠地“跳舞”。","kind":"narration","speaker":"旁白"},{"en":"It obviously could not tell the difference between Indian music and jazz!","zh":"显然，它分不出印度音乐和爵士乐之间的差别！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l043","number":43,"book":2,"title":"Over the South Pole","paragraphs":[{"index":0,"rows":[{"en":"In 1929, three years after his flight over the North Pole, the American explorer, R.E. Byrd, successfully flew over the South Pole for the first time.","zh":"1929年，也就是飞越北极三年之后，美国探险家R.E.伯德首次成功飞越了南极。","kind":"narration","speaker":"旁白"},{"en":"Though, at first, Byrd and his men were able to take a great many photographs of the mountains that lay below, they soon ran into serious trouble.","zh":"虽然起初伯德和同伴们拍下了许多下方群山的照片，但他们很快就遇上了严重的困难。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"At one point, it seemed certain that their plane would crash.","zh":"有一阵子，他们的飞机似乎肯定要坠毁了。","kind":"narration","speaker":"旁白"},{"en":"It could only get over the mountains if it rose to 10,000 feet.","zh":"飞机只有升到一万英尺的高度，才能飞越群山。","kind":"narration","speaker":"旁白"},{"en":"Byrd at once ordered his men to throw out two heavy food sacks.","zh":"伯德立刻命令同伴们把两袋沉重的食物扔出去。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The plane was then able to rise and it cleared the mountains by 400 feet.","zh":"飞机这才得以上升，从比山峰高四百英尺的地方飞越了群山。","kind":"narration","speaker":"旁白"},{"en":"Byrd now knew that he would be able to reach the South Pole which was 300 miles away, for there were no more mountains in sight.","zh":"这时伯德知道，他能够到达三百英里以外的南极了，因为视野中再也看不到山了。","kind":"narration","speaker":"旁白"},{"en":"The aircraft was able to fly over the endless white plains without difficulty.","zh":"飞机顺利地飞过了那无边无际的白色平原。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l044","number":44,"book":2,"title":"Through the forest","paragraphs":[{"index":0,"rows":[{"en":"Mrs. Anne Sterling did not think of the risk she was taking when she ran through a forest after two men.","zh":"安妮·斯特林太太在树林里追赶两名男子时，没有想到自己正冒着多大的风险。","kind":"narration","speaker":"旁白"},{"en":"They had rushed up to her while she was having a picnic at the edge of a forest with her children and tried to steal her handbag.","zh":"当时，她正和孩子们在树林边野餐，那两个人突然冲到她跟前，想抢她的手提包。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"In the struggle, the strap broke and, with the bag in their possession, both men started running through the trees.","zh":"在争夺中，包带断了，两名男子拿着包开始在树林里奔跑。","kind":"narration","speaker":"旁白"},{"en":"Mrs. Sterling got so angry that she ran after them.","zh":"斯特林太太气极了，便追赶他们。","kind":"narration","speaker":"旁白"},{"en":"She was soon out of breath, but she continued to run.","zh":"她很快就跑得气喘吁吁，但仍继续跑。","kind":"narration","speaker":"旁白"},{"en":"When she caught up with them, she saw that they had sat down and were going through the contents of the bag, so she ran straight at them.","zh":"她追上他们时，看见两个人已经坐下来，正在翻看包里的东西，于是径直向他们冲去。","kind":"narration","speaker":"旁白"},{"en":"The men got such a fright that they dropped the bag and ran away.","zh":"那两个人吓得扔下包就逃跑了。","kind":"narration","speaker":"旁白"},{"en":"‘The strap needs mending,’ said Mrs. Sterling later, ‘but they did not steal anything.’","zh":"“包带需要修一修，”斯特林太太后来说，“不过，他们什么也没偷走。”","kind":"speech","speaker":"斯特林太太","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l045","number":45,"book":2,"title":"A clear conscience","paragraphs":[{"index":0,"rows":[{"en":"The whole village soon learnt that a large sum of money had been lost.","zh":"整个村子很快就知道，有一大笔钱丢了。","kind":"narration","speaker":"旁白"},{"en":"Sam Benton, the local butcher, had lost his wallet while taking his savings to the post office.","zh":"当地的肉贩萨姆·本顿把积蓄送往邮局时，丢了钱包。","kind":"narration","speaker":"旁白"},{"en":"Sam was sure that the wallet must have been found by one of the villagers, but it was not returned to him.","zh":"萨姆确信钱包一定被某个村民捡到了，可是并没有人把钱包还给他。","kind":"narration","speaker":"旁白"},{"en":"Three months passed, and then one morning, Sam found his wallet outside his front door.","zh":"三个月过去了，一天早晨，萨姆在自己家门外找到了钱包。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It had been wrapped up in newspaper and it contained half the money he had lost, together with a note which said: ‘A thief, yes, but only 50 per cent a thief!’","zh":"钱包用报纸包着，里面有他所丢钱款的一半，还附着一张便条，上面写着：“没错，是个小偷，不过只算百分之五十的小偷！”","kind":"mixed","speaker":"旁白与便条作者","breakBefore":true},{"en":"Two months later, some more money was sent to Sam with another note: ‘Only 25 per cent a thief now!’","zh":"两个月后，又有人给萨姆送来一些钱，附着另一张便条：“现在只算百分之二十五的小偷了！”","kind":"mixed","speaker":"旁白与便条作者","breakBefore":true},{"en":"In time, all Sam’s money was paid back in this way.","zh":"过了一段时间，萨姆的钱就这样全部还清了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The last note said: ‘I am 100 per cent honest now!’","zh":"最后一张便条写着：“我现在是百分之百的老实人了！”","kind":"mixed","speaker":"旁白与便条作者","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l046","number":46,"book":2,"title":"Expensive and uncomfortable","paragraphs":[{"index":0,"rows":[{"en":"When a plane from London arrived at Sydney airport, workers began to unload a number of wooden boxes which contained clothing.","zh":"一架从伦敦飞来的飞机抵达悉尼机场后，工人们开始卸下一批装着衣服的木箱。","kind":"narration","speaker":"旁白"},{"en":"No one could account for the fact that one of the boxes was extremely heavy.","zh":"其中一个箱子格外沉重，谁也解释不了原因。","kind":"narration","speaker":"旁白"},{"en":"It suddenly occurred to one of the workers to open up the box.","zh":"一名工人突然想到把箱子打开看看。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He was astonished at what he found.","zh":"他看到箱子里的情形，大吃一惊。","kind":"narration","speaker":"旁白"},{"en":"A man was lying in the box on top of a pile of woollen goods.","zh":"一个男子躺在箱子里的一堆毛织品上。","kind":"narration","speaker":"旁白"},{"en":"He was so surprised at being discovered that he did not even try to run away.","zh":"他被人发现后，惊讶得连逃跑都没有尝试。","kind":"narration","speaker":"旁白"},{"en":"After he was arrested, the man admitted hiding in the box before the plane left London.","zh":"被捕后，这名男子承认自己是在飞机离开伦敦之前躲进箱子的。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He had had a long and uncomfortable trip, for he had been confined to the wooden box for over eighteen hours.","zh":"他经历了一趟漫长而难受的旅行，因为他被关在木箱里十八个多小时。","kind":"narration","speaker":"旁白"},{"en":"The man was ordered to pay £3,500 for the cost of the trip.","zh":"这名男子被勒令支付三千五百英镑的旅费。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The normal price of a ticket is £2,000!","zh":"正常票价是两千英镑！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l047","number":47,"book":2,"title":"A thirsty ghost","paragraphs":[{"index":0,"rows":[{"en":"A public house which was recently bought by Mr. Ian Thompson is up for sale.","zh":"伊恩·汤普森先生最近买下的一家酒馆，现在正挂牌出售。","kind":"narration","speaker":"旁白"},{"en":"Mr. Thompson is going to sell it because it is haunted.","zh":"汤普森先生打算卖掉酒馆，因为那里闹鬼。","kind":"narration","speaker":"旁白"},{"en":"He told me that he could not go to sleep one night because he heard a strange noise coming from the bar.","zh":"他告诉我，一天夜里，他听见酒吧间里传来一种奇怪的声音，因而无法入睡。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The next morning, he found that the doors had been blocked by chairs and the furniture had been moved.","zh":"第二天早晨，他发现门被椅子堵住了，家具也被挪动了。","kind":"narration","speaker":"旁白"},{"en":"Though Mr. Thompson had turned the lights off before he went to bed, they were on in the morning.","zh":"虽然汤普森先生睡前关了灯，可早晨灯却亮着。","kind":"narration","speaker":"旁白"},{"en":"He also said that he had found five empty whisky bottles which the ghost must have drunk the night before.","zh":"他还说，他发现了五个空威士忌酒瓶，一定是鬼在前一晚把里面的酒喝光了。","kind":"narration","speaker":"旁白"},{"en":"When I suggested that some villagers must have come in for a free drink, Mr. Thompson shook his head.","zh":"当我提出一定是一些村民进来喝了免费酒时，汤普森先生摇了摇头。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The villagers have told him that they will not accept the pub even if he gives it away.","zh":"村民们已经告诉他，即使他把酒馆白送给他们，他们也不要。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l048","number":48,"book":2,"title":"Did you want to tell me something?","paragraphs":[{"index":0,"rows":[{"en":"Dentists always ask questions when it is impossible for you to answer.","zh":"牙医总是在你不可能回答的时候提问。","kind":"narration","speaker":"旁白"},{"en":"My dentist had just pulled out one of my teeth and had told me to rest for a while.","zh":"我的牙医刚拔掉了我一颗牙，并叫我休息一会儿。","kind":"narration","speaker":"旁白"},{"en":"I tried to say something, but my mouth was full of cotton wool.","zh":"我想说点什么，可嘴里塞满了药棉。","kind":"narration","speaker":"旁白"},{"en":"He knew I collected match boxes and asked me whether my collection was growing.","zh":"他知道我收集火柴盒，便问我的收藏是不是又增加了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He then asked me how my brother was and whether I liked my new job in London.","zh":"接着，他又问我兄弟的近况，以及我是否喜欢在伦敦的新工作。","kind":"narration","speaker":"旁白"},{"en":"In answer to these questions I either nodded or made strange noises.","zh":"回答这些问题时，我不是点头，就是发出奇怪的声音。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, my tongue was busy searching out the hole where the tooth had been.","zh":"与此同时，我的舌头一直忙着寻找那颗牙原来所在的空洞。","kind":"narration","speaker":"旁白"},{"en":"I suddenly felt very worried, but could not say anything.","zh":"我突然很担心，却什么也说不出来。","kind":"narration","speaker":"旁白"},{"en":"When the dentist at last removed the cotton wool from my mouth, I was able to tell him that he had pulled out the wrong tooth.","zh":"牙医终于从我嘴里取出药棉时，我才得以告诉他，他把牙拔错了。","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l049","number":49,"book":2,"title":"The end of a dream","paragraphs":[{"index":0,"rows":[{"en":"Tired of sleeping on the floor, a young man in Teheran saved up for years to buy a real bed.","zh":"德黑兰有个年轻人厌倦了睡地板，为了买一张真正的床，他攒了好几年的钱。","kind":"narration","speaker":"旁白"},{"en":"For the first time in his life, he became the proud owner of a bed which had springs and a mattress.","zh":"他有生以来第一次拥有了一张带弹簧和床垫的床，心里十分得意。","kind":"narration","speaker":"旁白"},{"en":"Because the weather was very hot, he carried the bed on to the roof of his house.","zh":"由于天气很热，他把床搬到了自己家的屋顶上。","kind":"narration","speaker":"旁白"},{"en":"He slept very well for the first two nights, but on the third night, a storm blew up.","zh":"头两个晚上他睡得很好，可到了第三个晚上，突然刮起了风暴。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"A gust of wind swept the bed off the roof and sent it crashing into the courtyard below.","zh":"一阵狂风把床从屋顶卷了下去，使它重重地砸进下面的院子。","kind":"narration","speaker":"旁白"},{"en":"The young man did not wake up until the bed had struck the ground.","zh":"直到床撞到地面，年轻人才醒过来。","kind":"narration","speaker":"旁白"},{"en":"Although the bed was smashed to pieces, the man was miraculously unhurt.","zh":"虽然床摔得粉碎，他却奇迹般地毫发无伤。","kind":"narration","speaker":"旁白"},{"en":"When he woke up, he was still on the mattress.","zh":"醒来时，他仍然躺在床垫上。","kind":"narration","speaker":"旁白"},{"en":"Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house.","zh":"他瞥了一眼散落在周围的木头和金属碎片，伤心地捡起床垫，把它搬进屋里。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"After he had put it on the floor, he promptly went to sleep again.","zh":"他把床垫放在地板上，随即又睡着了。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l050","number":50,"book":2,"title":"Taken for a ride","paragraphs":[{"index":0,"rows":[{"en":"I love travelling in the country, but I don’t like losing my way.","zh":"我喜欢到乡间旅行，但不喜欢迷路。","kind":"narration","speaker":"旁白"},{"en":"I went on an excursion recently, but my trip took me longer than I expected.","zh":"最近我出去游玩了一趟，但这次旅行花的时间比我预计的长。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘I'm going to Woodford Green,’ I said to the conductor as I got on the bus, ‘but I don’t know where it is.’","zh":"“我要去伍德福德格林，”上公共汽车时，我对售票员说，“可是我不知道那地方在哪里。”","kind":"speech","speaker":"我"}]},{"index":2,"rows":[{"en":"‘I'll tell you where to get off,’ answered the conductor.","zh":"“我会告诉你在哪里下车，”售票员回答。","kind":"speech","speaker":"售票员"}]},{"index":3,"rows":[{"en":"I sat in the front of the bus to get a good view of the countryside.","zh":"为了好好欣赏乡村风光，我坐在车厢前部。","kind":"narration","speaker":"旁白"},{"en":"After some time, the bus stopped.","zh":"过了一段时间，公共汽车停了下来。","kind":"narration","speaker":"旁白"},{"en":"Looking round, I realized with a shock that I was the only passenger left on the bus.","zh":"我环顾四周，惊讶地发现车上只剩我一个乘客了。","kind":"narration","speaker":"旁白"}]},{"index":4,"rows":[{"en":"‘You'll have to get off here,’ the conductor said.","zh":"“你得在这里下车了，”售票员说。","kind":"speech","speaker":"售票员"},{"en":"‘This is as far as we go.’","zh":"“我们就开到这里。”","kind":"speech","speaker":"售票员"}]},{"index":5,"rows":[{"en":"‘Is this Woodford Green?’ I asked.","zh":"“这里是伍德福德格林吗？”我问。","kind":"speech","speaker":"我"}]},{"index":6,"rows":[{"en":"‘Oh dear,’ said the conductor suddenly.","zh":"“哎呀，”售票员突然说。","kind":"speech","speaker":"售票员"},{"en":"‘I forgot to put you off.’ .","zh":"“我忘了叫你下车。”","kind":"speech","speaker":"售票员"}]},{"index":7,"rows":[{"en":"‘It doesn’t matter,’ I said.","zh":"“没关系，”我说。","kind":"speech","speaker":"我"},{"en":"‘I'll get off here.’","zh":"“我就在这里下车吧。”","kind":"speech","speaker":"我"}]},{"index":8,"rows":[{"en":"‘We're going back now,’ said the conductor.","zh":"“我们现在要往回开了，”售票员说。","kind":"speech","speaker":"售票员"}]},{"index":9,"rows":[{"en":"‘Well, in that case, I prefer to stay on the bus,’ I answered.","zh":"“哦，既然这样，我还是留在车上吧，”我回答。","kind":"speech","speaker":"我"}]}]},{"lessonId":"nce-b2-eef57c-l051","number":51,"book":2,"title":"Reward for virtue","paragraphs":[{"index":0,"rows":[{"en":"My friend, Hugh, has always been fat, but things got so bad recently that he decided to go on a diet.","zh":"我的朋友休一直很胖，但最近胖得实在厉害，于是他决定节食。","kind":"narration","speaker":"旁白"},{"en":"He began his diet a week ago.","zh":"他是一周前开始节食的。","kind":"narration","speaker":"旁白"},{"en":"First of all, he wrote out a long list of all the foods which were forbidden.","zh":"首先，他写了一张长长的清单，列出所有禁止食用的食物。","kind":"narration","speaker":"旁白"},{"en":"The list included most of the things Hugh loves: butter, potatoes, rice, beer, milk, chocolate, and sweets.","zh":"这张清单包括休爱吃的大多数东西：黄油、土豆、米饭、啤酒、牛奶、巧克力和糖果。","kind":"narration","speaker":"旁白"},{"en":"Yesterday I paid him a visit.","zh":"昨天，我去看望他。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"I rang the bell and was not surprised to see that Hugh was still as fat as ever.","zh":"我按了门铃，看到休仍然像以前一样胖，一点也不意外。","kind":"narration","speaker":"旁白"},{"en":"He led me into his room and hurriedly hid a large parcel under his desk.","zh":"他把我领进自己的房间，慌忙把一个大包裹藏到书桌下面。","kind":"narration","speaker":"旁白"},{"en":"It was obvious that he was very embarrassed.","zh":"很明显，他十分尴尬。","kind":"narration","speaker":"旁白"},{"en":"When I asked him what he was doing, he smiled guiltily and then put the parcel on the desk.","zh":"我问他在做什么时，他心虚地笑了笑，随后把包裹放到了书桌上。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He explained that his diet was so strict that he had to reward himself occasionally.","zh":"他解释说，自己节食太严格了，偶尔必须奖励一下自己。","kind":"narration","speaker":"旁白"},{"en":"Then he showed me the contents of the parcel.","zh":"接着，他给我看了包裹里的东西。","kind":"narration","speaker":"旁白"},{"en":"It contained five large bars of chocolate and three bags of sweets!","zh":"里面装着五大块巧克力和三袋糖果！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l052","number":52,"book":2,"title":"A pretty carpet","paragraphs":[{"index":0,"rows":[{"en":"We have just moved into a new house and I have been working hard all morning.","zh":"我们刚搬进一所新房子，我整个上午一直都在忙碌。","kind":"narration","speaker":"旁白"},{"en":"I have been trying to get my new room in order.","zh":"我一直在设法把自己的新房间整理好。","kind":"narration","speaker":"旁白"},{"en":"This has not been easy because I own over a thousand books.","zh":"这并不容易，因为我有一千多本书。","kind":"narration","speaker":"旁白"},{"en":"To make matters worse, the room is rather small, so I have temporarily put my books on the floor.","zh":"更糟的是，房间相当小，所以我暂时把书放在了地板上。","kind":"narration","speaker":"旁白"},{"en":"At the moment, they cover every inch of floor space and I actually have to walk on them to get in or out of the room.","zh":"现在，书铺满了地板的每一寸地方，我进出房间竟然得踩着书走。","kind":"narration","speaker":"旁白"},{"en":"A short while ago, my sister helped me to carry one of my old bookcases up the stairs.","zh":"不久前，我的一位姐妹帮我把一个旧书柜搬上了楼。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"She went into my room and got a big surprise when she saw all those books on the floor.","zh":"她走进我的房间，看见地板上的那些书，大吃一惊。","kind":"narration","speaker":"旁白"},{"en":"‘This is the prettiest carpet I have ever seen,’ she said.","zh":"“这是我见过的最漂亮的地毯，”她说。","kind":"speech","speaker":"我的姐妹","breakBefore":true},{"en":"She gazed at it for some time then added, ‘You don’t need bookcases at all.","zh":"她盯着看了一会儿，又补充道：“你根本不需要书柜。”","kind":"mixed","speaker":"旁白与我的姐妹"},{"en":"You can sit here in your spare time and read the carpet!’","zh":"“空闲的时候，你可以坐在这里，读这块地毯！”","kind":"speech","speaker":"我的姐妹"}]}]},{"lessonId":"nce-b2-eef57c-l053","number":53,"book":2,"title":"Hot snake","paragraphs":[{"index":0,"rows":[{"en":"At last firemen have put out a big forest fire in California.","zh":"消防队员终于扑灭了加利福尼亚州的一场森林大火。","kind":"narration","speaker":"旁白"},{"en":"Since then, they have been trying to find out how the fire began.","zh":"此后，他们一直在设法查明火灾是怎么发生的。","kind":"narration","speaker":"旁白"},{"en":"Forest fires are often caused by broken glass or by cigarette ends which people carelessly throw away.","zh":"森林火灾常常是由碎玻璃，或人们随手乱扔的烟头引起的。","kind":"narration","speaker":"旁白"},{"en":"Yesterday the firemen examined the ground carefully, but were not able to find any broken glass.","zh":"昨天，消防队员仔细检查了地面，却没有找到任何碎玻璃。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"They were also quite sure that a cigarette end did not start the fire.","zh":"他们也十分肯定，这场火不是烟头引起的。","kind":"narration","speaker":"旁白"},{"en":"This morning, however, a firemen accidentally discovered the cause.","zh":"然而，今天早晨，一名消防队员意外发现了起火原因。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He noticed the remains of a snake which was wound round the electric wires of a 16,000-volt power line.","zh":"他发现了一条蛇的残骸，缠在一条一万六千伏高压输电线路的电线上。","kind":"narration","speaker":"旁白"},{"en":"In this way, he was able to solve the mystery.","zh":"就这样，他解开了这个谜。","kind":"narration","speaker":"旁白"},{"en":"The explanation was simple but very unusual.","zh":"原因很简单，却十分罕见。","kind":"narration","speaker":"旁白"},{"en":"A bird had snatched up the snake from the ground and then dropped it on to the wires.","zh":"一只鸟先从地上叼起了那条蛇，后来又把它丢到了电线上。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The snake then wound itself round the wires.","zh":"蛇随后把身体缠在了电线上。","kind":"narration","speaker":"旁白"},{"en":"When it did so, it sent sparks down to the ground and these immediately started a fire.","zh":"蛇这么一缠，便使火花落到地面，立刻引起了火灾。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l054","number":54,"book":2,"title":"Sticky fingers","paragraphs":[{"index":0,"rows":[{"en":"After breakfast, I sent the children to school and then I went to the shops.","zh":"早饭后，我把孩子们送到学校，然后去商店买东西。","kind":"narration","speaker":"旁白"},{"en":"It was still early when I returned home.","zh":"我回到家时还很早。","kind":"narration","speaker":"旁白"},{"en":"The children were at school, my husband was at work and the house was quiet.","zh":"孩子们在上学，丈夫在上班，屋里静悄悄的。","kind":"narration","speaker":"旁白"},{"en":"So I decided to make some meat pies.","zh":"于是，我决定做些肉馅饼。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"In a short time I was busy mixing butter and flour and my hands were soon covered with sticky pastry.","zh":"不一会儿，我就忙着把黄油和面粉混在一起，双手很快便沾满了黏糊糊的面团。","kind":"narration","speaker":"旁白"},{"en":"At exactly that moment, the telephone rang.","zh":"偏偏就在那一刻，电话铃响了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Nothing could have been more annoying.","zh":"真没有比这更烦人的事了。","kind":"narration","speaker":"旁白"},{"en":"I picked up the receiver between two sticky fingers and was dismayed when I recognized the voice of Helen Bates.","zh":"我用两个黏糊糊的手指夹起听筒，一听出是海伦·贝茨的声音，心里顿时发愁。","kind":"narration","speaker":"旁白"},{"en":"It took me ten minutes to persuade her to ring back later.","zh":"我花了十分钟，才说服她过一会儿再打来。","kind":"narration","speaker":"旁白"},{"en":"At last I hung up the receiver.","zh":"最后，我挂上了听筒。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"What a mess!","zh":"真是一团糟！","kind":"narration","speaker":"旁白"},{"en":"There was pastry on my fingers, on the telephone, and on the doorknobs.","zh":"我的手指上、电话上，连门把手上都沾着面团。","kind":"narration","speaker":"旁白"},{"en":"I had no sooner got back to the kitchen than the doorbell rang loud enough to wake the dead.","zh":"我刚回到厨房，门铃就响了，那声音大得简直能把死人吵醒。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"This time it was the postman and he wanted me to sign for a registered letter!","zh":"这回是邮递员来了，他要我签收一封挂号信！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l055","number":55,"book":2,"title":"Not a gold mine","paragraphs":[{"index":0,"rows":[{"en":"Dreams of finding lost treasure almost came true recently.","zh":"最近，找到失落宝藏的梦想差一点就实现了。","kind":"narration","speaker":"旁白"},{"en":"A new machine called ‘The Revealer’ has been invented and it has been used to detect gold which has been buried in the ground.","zh":"一种名叫“探宝者”的新机器已经被发明出来，并被用来探测埋在地下的黄金。","kind":"narration","speaker":"旁白"},{"en":"The machine was used in a cave near the seashore where — it is said — pirates used to hide gold.","zh":"人们在海边的一个山洞里使用了这台机器，据说海盗从前常在那里藏金子。","kind":"narration","speaker":"旁白"},{"en":"The pirates would often bury gold in the cave and then fail to collect it.","zh":"海盗常常把黄金埋进山洞里，后来却没能取走。","kind":"narration","speaker":"旁白"},{"en":"Armed with the new machine, a search party went into the cave hoping to find buried treasure.","zh":"一支搜寻队带着这台新机器进入山洞，希望找到埋藏的财宝。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The leader of the party was examining the soil near the entrance to the cave when the machine showed that there was gold under the ground.","zh":"队长正在检查洞口附近的泥土时，机器显示地下有黄金。","kind":"narration","speaker":"旁白"},{"en":"Very excited, the party dug a hole two feet deep.","zh":"队员们激动极了，挖了一个两英尺深的坑。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"They finally found a small gold coin which was almost worthless.","zh":"他们最后找到了一枚几乎不值钱的小金币。","kind":"narration","speaker":"旁白"},{"en":"The party then searched the whole cave thoroughly but did not find anything except an empty tin trunk.","zh":"随后，搜寻队彻底搜查了整个山洞，但除了一只空铁皮箱，什么也没找到。","kind":"narration","speaker":"旁白"},{"en":"In spite of this, many people are confident that ‘The Revealer’ may reveal something of value fairly soon.","zh":"尽管如此，许多人仍然相信，“探宝者”很快就有可能找到有价值的东西。","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l056","number":56,"book":2,"title":"Faster than sound!","paragraphs":[{"index":0,"rows":[{"en":"Once a year, a race is held for old cars.","zh":"老爷车比赛每年举行一次。","kind":"narration","speaker":"旁白"},{"en":"A lot of cars entered for this race last year and there was a great deal of excitement just before it began.","zh":"去年，许多汽车报名参加这场比赛，比赛开始前，现场十分热闹。","kind":"narration","speaker":"旁白"},{"en":"One of the most handsome cars was a Rolls-Royce Silver Ghost.","zh":"最漂亮的汽车之一是一辆劳斯莱斯“银魅”。","kind":"narration","speaker":"旁白"},{"en":"The most unusual car was a Benz which had only three wheels.","zh":"最特别的汽车是一辆只有三个轮子的奔驰车。","kind":"narration","speaker":"旁白"},{"en":"Built in 1885, it was the oldest car taking part.","zh":"这辆车造于1885年，是参赛车辆中年代最久的。","kind":"narration","speaker":"旁白"},{"en":"After a great many loud explosions, the race began.","zh":"一阵阵响亮的爆鸣声过后，比赛开始了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Many of the cars broke down on the course and some drivers spent more time under their cars than in them!","zh":"许多汽车在赛道上抛了锚，有些司机待在车底下的时间，比坐在车里的时间还多！","kind":"narration","speaker":"旁白"},{"en":"A few cars, however, completed the race.","zh":"不过，还是有几辆汽车跑完了全程。","kind":"narration","speaker":"旁白"},{"en":"The winning car reached a speed of forty miles an hour — much faster than any of its rivals.","zh":"获胜的那辆车达到了每小时四十英里的速度，比任何对手都快得多。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It sped downhill at the end of the race and its driver had a lot of trouble trying to stop it.","zh":"比赛快结束时，它飞快地冲下斜坡，司机费了很大劲才把它停住。","kind":"narration","speaker":"旁白"},{"en":"The race gave everyone a great deal of pleasure.","zh":"这场比赛给大家带来了许多欢乐。","kind":"narration","speaker":"旁白"},{"en":"It was very different from modern car races but no less exciting.","zh":"它与现代赛车比赛大不相同，却同样令人兴奋。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l057","number":57,"book":2,"title":"Can I help you, madam?","paragraphs":[{"index":0,"rows":[{"en":"A woman in jeans stood at the window of an expensive shop.","zh":"一位穿着牛仔裤的女士站在一家高档商店的橱窗前。","kind":"narration","speaker":"旁白"},{"en":"Though she hesitated for a moment, she finally went in and asked to see a dress that was in the window.","zh":"虽然犹豫了一会儿，她最终还是走进店里，要求看看橱窗中的一件连衣裙。","kind":"narration","speaker":"旁白"},{"en":"The assistant who served her did not like the way she was dressed.","zh":"接待她的店员不喜欢她的穿着。","kind":"narration","speaker":"旁白"},{"en":"Glancing at her scornfully, he told her that the dress was sold.","zh":"他轻蔑地瞥了她一眼，告诉她那件连衣裙已经卖掉了。","kind":"narration","speaker":"旁白"},{"en":"The woman walked out of the shop angrily and decided to punish the assistant next day.","zh":"女士生气地走出商店，决定第二天教训一下这个店员。","kind":"narration","speaker":"旁白"},{"en":"She returned to the shop the following morning dressed in a fur coat, with a handbag in one hand and a long umbrella in the other.","zh":"第二天早晨，她穿着一件裘皮大衣回到商店，一手提着手袋，另一手拿着一把长柄雨伞。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"After seeking out the rude assistant, she asked for the same dress.","zh":"找到那个无礼的店员后，她要求看同一件连衣裙。","kind":"narration","speaker":"旁白"},{"en":"Not realizing who she was, the assistant was eager to serve her this time.","zh":"店员没有认出她，这一次十分殷勤地为她服务。","kind":"narration","speaker":"旁白"},{"en":"With great difficulty, he climbed into the shop window to get the dress.","zh":"他费了很大劲爬进橱窗，去取那件连衣裙。","kind":"narration","speaker":"旁白"},{"en":"As soon as she saw it, the woman said she did not like it.","zh":"女士一看到裙子，就说自己不喜欢。","kind":"narration","speaker":"旁白"},{"en":"She enjoyed herself making the assistant bring almost everything in the window before finally buying the dress she had first asked for.","zh":"她兴致勃勃地让店员把橱窗里的东西几乎全拿了出来，最后才买下她一开始指名要的那件连衣裙。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l058","number":58,"book":2,"title":"A blessing in disguise?","paragraphs":[{"index":0,"rows":[{"en":"The tiny village of Frinley is said to possess a ‘cursed tree’.","zh":"据说，弗林利这个小村庄里有一棵“受了诅咒的树”。","kind":"narration","speaker":"旁白"},{"en":"Because the tree was mentioned in a newspaper, the number of visitors to Frinley has now increased.","zh":"由于一家报纸提到了这棵树，现在到弗林利来的游客人数增加了。","kind":"narration","speaker":"旁白"},{"en":"The tree was planted near the church fifty years ago, but it is only in recent years that it has gained an evil reputation.","zh":"这棵树是五十年前种在教堂附近的，但直到近几年才有了不祥的名声。","kind":"narration","speaker":"旁白"},{"en":"It is said that if anyone touches the tree, he will have bad luck; if he picks a leaf, he will die.","zh":"据说，谁要是碰了这棵树，就会倒霉；谁要是摘下一片叶子，就会死去。","kind":"narration","speaker":"旁白"},{"en":"Many villagers believe that the tree has already claimed a number of victims.","zh":"许多村民相信，这棵树已经夺走了好几个人的性命。","kind":"narration","speaker":"旁白"},{"en":"The vicar has been asked to have the tree cut down, but so far he has refused.","zh":"有人请牧师让人把树砍掉，但到目前为止，他一直拒绝这样做。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He has pointed out that the tree is a useful source of income, as tourists have been coming from all parts of the country to see it.","zh":"他指出，这棵树是一个很有用的收入来源，因为全国各地的游客都一直赶来看它。","kind":"narration","speaker":"旁白"},{"en":"In spite of all that has been said, the tourists have been picking leaves and cutting their names on the tree-trunk.","zh":"尽管有这些说法，游客们还是一直在摘树叶，并把自己的名字刻在树干上。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"So far, not one of them has been struck down by sudden death!","zh":"到现在为止，他们中还没有一个人突然死去！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l059","number":59,"book":2,"title":"In or out?","paragraphs":[{"index":0,"rows":[{"en":"Our dog, Rex, used to sit outside our front gate and bark.","zh":"我们家的狗雷克斯以前常坐在大门外面叫。","kind":"narration","speaker":"旁白"},{"en":"Every time he wanted to come into the garden he would bark until someone opened the gate.","zh":"每次它想进花园时，就一直叫，直到有人把门打开。","kind":"narration","speaker":"旁白"},{"en":"As the neighbours complained of the noise, my husband spent weeks training him to press his paw on the latch to let himself in.","zh":"由于邻居们抱怨太吵，我丈夫花了好几个星期，训练它用爪子按门闩，让自己进来。","kind":"narration","speaker":"旁白"},{"en":"Rex soon became an expert at opening the gate.","zh":"雷克斯很快就成了开门能手。","kind":"narration","speaker":"旁白"},{"en":"However, when I was going out shopping last week, I noticed him in the garden near the gate.","zh":"可是上周我出门买东西时，看见它在花园里靠近大门的地方。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"This time he was barking so that someone would let him out!","zh":"这一回，它叫个不停，是想让人把它放出去！","kind":"narration","speaker":"旁白"},{"en":"Since then, he has developed another bad habit.","zh":"从那以后，它又养成了另一个坏习惯。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"As soon as he opens the gate from the outside, he comes into the garden and waits until the gate shuts.","zh":"它一从外面把门打开，就走进花园，等着门关上。","kind":"narration","speaker":"旁白"},{"en":"Then he sits and barks until someone lets him out.","zh":"然后，它就坐在那里叫，直到有人把它放出去。","kind":"narration","speaker":"旁白"},{"en":"After this he immediately lets himself in and begins barking again.","zh":"这之后，它立刻又自己开门进来，接着再叫。","kind":"narration","speaker":"旁白"},{"en":"Yesterday my husband removed the gate and Rex got so annoyed we have not seen him since.","zh":"昨天，我丈夫把大门拆掉了，雷克斯气坏了，从那以后我们就再也没有见到它。","kind":"narration","speaker":"旁白","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l060","number":60,"book":2,"title":"The future","paragraphs":[{"index":0,"rows":[{"en":"At a village fair, I decided to visit a fortune-teller called Madam Bellinsky.","zh":"在一次乡村集市上，我决定去找一位叫贝林斯基夫人的算命者。","kind":"narration","speaker":"旁白"},{"en":"I went into her tent and she told me to sit down.","zh":"我走进她的帐篷，她让我坐下。","kind":"narration","speaker":"旁白"},{"en":"After I had given her some money, she looked into a crystal ball and said: ‘A relation of yours is coming to see you.","zh":"我给了她一些钱后，她望着一个水晶球说：“你的一位亲戚要来看你。”","kind":"mixed","speaker":"旁白与贝林斯基夫人","breakBefore":true},{"en":"She will be arriving this evening and intends to stay for a few days.","zh":"“她今天傍晚就会到，打算住几天。”","kind":"speech","speaker":"贝林斯基夫人"},{"en":"The moment you leave this tent, you will get a big surprise.","zh":"“你一离开这顶帐篷，就会大吃一惊。”","kind":"speech","speaker":"贝林斯基夫人"},{"en":"A woman you know well will rush towards you.","zh":"“一位你很熟悉的女人会向你跑来。”","kind":"speech","speaker":"贝林斯基夫人"},{"en":"She will speak to you and then she will lead you away from this place.","zh":"“她会跟你说话，然后领你离开这里。”","kind":"speech","speaker":"贝林斯基夫人"},{"en":"That is all.’","zh":"“就这些。”","kind":"speech","speaker":"贝林斯基夫人"}]},{"index":1,"rows":[{"en":"As soon as I went outside, I forgot all about Madam Bellinsky because my wife hurried towards me.","zh":"我一走出去，就把贝林斯基夫人的事忘得一干二净了，因为我的妻子正急匆匆地朝我走来。","kind":"narration","speaker":"旁白"},{"en":"‘Where have you been hiding?’ she asked impatiently.","zh":"“你躲到哪里去了？”她不耐烦地问。","kind":"speech","speaker":"妻子"},{"en":"‘Your sister will be here in less than an hour and we must be at the station to meet her.","zh":"“你的姐妹不到一个小时就会到，我们必须到车站去接她。”","kind":"speech","speaker":"妻子"},{"en":"We are late already.’","zh":"“我们已经晚了。”","kind":"speech","speaker":"妻子"},{"en":"As she walked away, I followed her out of the fair.","zh":"她转身走开，我便跟着她离开了集市。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l061","number":61,"book":2,"title":"Trouble with the Hubble","paragraphs":[{"index":0,"rows":[{"en":"The Hubble telescope was launched into space by NASA on April 20, 1990 at a cost of over a billion dollars.","zh":"哈勃望远镜于1990年4月20日由美国国家航空航天局发射升空，耗资超过十亿美元。","kind":"narration","speaker":"旁白"},{"en":"Right from the start there was trouble with the Hubble.","zh":"从一开始，哈勃望远镜就出了问题。","kind":"narration","speaker":"旁白"},{"en":"The pictures it sent us were very disappointing because its main mirror was faulty!","zh":"它传回的图像令人十分失望，因为它的主反射镜有缺陷！","kind":"narration","speaker":"旁白"},{"en":"NASA is now going to put the telescope right, so it will soon be sending up four astronauts to repair it.","zh":"现在，美国国家航空航天局打算把望远镜修好，因此很快就会把四名宇航员送上太空进行维修。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The shuttle Endeavour will be taking the astronauts to the Hubble.","zh":"“奋进”号航天飞机将把宇航员送到哈勃望远镜那里。","kind":"narration","speaker":"旁白"},{"en":"A robot-arm from the Endeavour will grab the telescope and hold it while the astronauts make the necessary repairs.","zh":"“奋进”号上的机械臂将抓住望远镜并将它固定住，让宇航员进行必要的维修。","kind":"narration","speaker":"旁白"},{"en":"Of course, the Hubble is above the earth’s atmosphere, so it will soon be sending us the clearest pictures of the stars and distant galaxies that we have ever seen.","zh":"当然，哈勃位于地球大气层之外，因此很快就会向我们传回前所未有的清晰图像，展现恒星和遥远的星系。","kind":"narration","speaker":"旁白"},{"en":"The Hubble will tell us a great deal about the age and size of the universe.","zh":"哈勃将告诉我们许多有关宇宙年龄和大小的事情。","kind":"narration","speaker":"旁白"},{"en":"By the time you read this, the Hubble's eagle eye will have sent us thousands and thousands of wonderful pictures.","zh":"等你读到这篇文章时，哈勃那只锐利的“鹰眼”就已经向我们传回了成千上万张精彩的照片。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l062","number":62,"book":2,"title":"After the fire","paragraphs":[{"index":0,"rows":[{"en":"Firemen had been fighting the forest fire for nearly three weeks before they could get it under control.","zh":"消防队员与这场森林大火搏斗了将近三个星期，才把火势控制住。","kind":"narration","speaker":"旁白"},{"en":"A short time before, great trees had covered the countryside for miles around.","zh":"不久以前，周围绵延数英里的乡野还长满了参天大树。","kind":"narration","speaker":"旁白"},{"en":"Now, smoke still rose up from the warm ground over the desolate hills.","zh":"如今，荒凉的山坡上，仍有烟从温热的地面升起。","kind":"narration","speaker":"旁白"},{"en":"Winter was coming on and the hills threatened the surrounding villages with destruction, for heavy rain would not only wash away the soil but would cause serious floods as well.","zh":"冬天快到了，这些山坡给周围的村庄带来了毁灭的威胁，因为大雨不仅会冲走泥土，还会造成严重的洪水。","kind":"narration","speaker":"旁白"},{"en":"When the fire had at last been put out, the forest authorities ordered several tons of a special type of grass-seed which would grow quickly.","zh":"大火终于扑灭后，林业部门订购了数吨生长迅速的特殊草籽。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"The seed was sprayed over the ground in huge quantities by aeroplanes.","zh":"飞机把大量草籽撒到了地面上。","kind":"narration","speaker":"旁白"},{"en":"The planes had been planting seed for nearly a month when it began to rain.","zh":"飞机播撒草籽将近一个月时，天开始下雨了。","kind":"narration","speaker":"旁白"},{"en":"By then, however, in many places the grass had already taken root.","zh":"不过，到那时，许多地方的草已经扎下了根。","kind":"narration","speaker":"旁白"},{"en":"In place of the great trees which had been growing there for centuries, patches of green had begun to appear in the blackened soil.","zh":"原先几个世纪以来一直长着参天大树的地方，如今在焦黑的泥土上已经开始出现一片片新绿。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l063","number":63,"book":2,"title":"She was not amused","paragraphs":[{"index":0,"rows":[{"en":"Jeremy Hampden has a large circle of friends and is very popular at parties.","zh":"杰里米·汉普登交友广泛，在聚会上很受欢迎。","kind":"narration","speaker":"旁白"},{"en":"Everybody admires him for his great sense of humour — everybody. that is, except his six-year-old daughter, Jenny.","zh":"人人都佩服他出众的幽默感——确切地说，除了他六岁的女儿珍妮以外，人人都是如此。","kind":"narration","speaker":"旁白"},{"en":"Recently, one of Jeremy's closest friends asked him to make a speech at a wedding reception.","zh":"最近，杰里米一位最要好的朋友请他在婚宴上讲几句话。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"This is the sort of thing that Jeremy loves.","zh":"这正是杰里米喜欢做的事。","kind":"narration","speaker":"旁白"},{"en":"He prepared the speech carefully and went to the wedding with Jenny.","zh":"他认真准备了讲话，并带着珍妮去参加婚礼。","kind":"narration","speaker":"旁白"},{"en":"He had included a large number of funny stories in the speech and, of course, it was a great success.","zh":"他在讲话中穿插了许多有趣的故事，当然，讲话大获成功。","kind":"narration","speaker":"旁白"},{"en":"As soon as he had finished, Jenny told him she wanted to go home.","zh":"他刚讲完，珍妮就告诉他，她想回家。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Jeremy was a little disappointed by this but he did as his daughter asked.","zh":"杰里米对此有些失望，不过还是照女儿的意思做了。","kind":"narration","speaker":"旁白"},{"en":"On the way home, he asked Jenny if she had enjoyed the speech.","zh":"回家的路上，他问珍妮是否喜欢他的讲话。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"To his surprise, she said she hadn’t.","zh":"让他吃惊的是，她说不喜欢。","kind":"narration","speaker":"旁白"},{"en":"Jeremy asked her why this was so and she told him that she did not like to see so many people laughing at him!","zh":"杰里米问她为什么，她告诉他，自己不喜欢看到那么多人嘲笑他！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l064","number":64,"book":2,"title":"The Channel Tunnel","paragraphs":[{"index":0,"rows":[{"en":"In 1858, a French engineer, Aimé Thomé de Gamond, arrived in England with a plan for a twenty-one-mile tunnel under the English Channel.","zh":"1858年，法国工程师艾梅·托梅·德·加蒙带着一项计划来到英国，打算在英吉利海峡下面修建一条二十一英里长的隧道。","kind":"narration","speaker":"旁白"},{"en":"He said that it would be possible to build a platform in the centre of the Channel.","zh":"他说，可以在海峡中央建造一个平台。","kind":"narration","speaker":"旁白"},{"en":"This platform would serve as a port and a railway station.","zh":"这个平台将兼作港口和火车站。","kind":"narration","speaker":"旁白"},{"en":"The tunnel would be well-ventilated if tall chimneys were built above sea level.","zh":"如果在海面上方建造高高的通风烟囱，隧道内就能保持良好的通风。","kind":"narration","speaker":"旁白"},{"en":"In 1860, a better plan was put forward by an Englishman, William Low.","zh":"1860年，一位名叫威廉·洛的英国人提出了一个更好的方案。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"He suggested that a double railway-tunnel should be built.","zh":"他建议修建两条并行的铁路隧道。","kind":"narration","speaker":"旁白"},{"en":"This would solve the problem of ventilation, for if a train entered this tunnel, it would draw in fresh air behind it.","zh":"这将解决通风问题，因为火车驶入这条隧道时，会从后方带入新鲜空气。","kind":"narration","speaker":"旁白"},{"en":"Forty-two years later a tunnel was actually begun.","zh":"四十二年后，隧道工程真的开工了。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"If, at the time, the British had not feared invasion, it would have been completed.","zh":"如果当时英国人没有害怕遭到入侵，隧道本来就能修建完成。","kind":"narration","speaker":"旁白"},{"en":"The world had to wait almost another 100 years for the Channel Tunnel.","zh":"世界又等了将近一百年，才等来海峡隧道。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"It was officially opened on March 7, 1994, finally connecting Britain to the European continent.","zh":"它于1994年3月7日正式开通，终于把英国与欧洲大陆连接起来。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l065","number":65,"book":2,"title":"Jumbo versus the police","paragraphs":[{"index":0,"rows":[{"en":"Last Christmas, the circus owner, Jimmy Gates, decided to take some presents to a children’s hospital.","zh":"去年圣诞节，马戏团老板吉米·盖茨决定给一家儿童医院送些礼物。","kind":"narration","speaker":"旁白"},{"en":"Dressed up as Father Christmas and accompanied by a ‘guard of honour’ of six pretty girls, he set off down the main street of the city riding a baby elephant called Jumbo.","zh":"他装扮成圣诞老人，在由六位漂亮姑娘组成的“仪仗队”陪同下，骑着一头名叫江伯的小象，沿着城里的主要街道出发了。","kind":"narration","speaker":"旁白"},{"en":"He should have known that the police would never allow this sort of thing.","zh":"他本该知道，警察绝不会允许这种事情发生。","kind":"narration","speaker":"旁白"},{"en":"A policeman approached Jimmy and told him he ought to have gone along a side street as Jumbo was holding up the traffic.","zh":"一名警察走到吉米面前，告诉他本来应该走一条小街，因为江伯堵塞了交通。","kind":"narration","speaker":"旁白"},{"en":"Though Jimmy agreed to go at once, Jumbo refused to move.","zh":"虽然吉米同意马上离开，江伯却不肯挪动。","kind":"narration","speaker":"旁白"},{"en":"Fifteen policemen had to push very hard to get him off the main street.","zh":"十五名警察不得不用力推，才把它推出主要街道。","kind":"narration","speaker":"旁白"},{"en":"The police had a difficult time, but they were most amused.","zh":"警察们忙得够呛，却觉得十分有趣。","kind":"narration","speaker":"旁白"},{"en":"‘Jumbo must weigh a few tons,’ said a policeman afterwards, ‘so it was fortunate that we didn’t have to carry him.","zh":"“江伯肯定有好几吨重，”一名警察事后说，“所以幸好我们不用抬着它走。","kind":"speech","speaker":"警察","breakBefore":true},{"en":"Of course, we should arrest him, but as he has a good record, we shall let him off this time.’","zh":"当然，我们应该逮捕它，不过既然它一贯表现良好，这回我们就饶了它吧。”","kind":"speech","speaker":"警察"}]}]},{"lessonId":"nce-b2-eef57c-l066","number":66,"book":2,"title":"Sweet as honey!","paragraphs":[{"index":0,"rows":[{"en":"In 1963 a Lancaster bomber crashed on Wallis Island, a remote place in the South Pacific, a long way west of Samoa.","zh":"1963年，一架兰开斯特轰炸机坠毁在瓦利斯岛上；那是南太平洋中一处偏僻的地方，位于萨摩亚以西很远的海域。","kind":"narration","speaker":"旁白"},{"en":"The plane wasn’t too badly damaged, but over the years, the crash was forgotten and the wreck remained undisturbed.","zh":"飞机损坏得并不太严重，但多年过去，坠机事件被人遗忘了，飞机残骸也一直无人碰过。","kind":"narration","speaker":"旁白"},{"en":"Then in 1989, twenty-six years after the crash, the plane was accidentally rediscovered in an aerial survey of the island.","zh":"后来到了1989年，也就是坠机二十六年后，人们在对该岛进行一次航空勘测时，意外地重新发现了这架飞机。","kind":"narration","speaker":"旁白"},{"en":"By this time, a Lancaster bomber in reasonable condition was rare and worth rescuing.","zh":"到这时，保存状况还算良好的兰开斯特轰炸机已经十分罕见，值得抢救。","kind":"narration","speaker":"旁白"},{"en":"The French authorities had the plane packaged and moved in parts back to France.","zh":"法国有关部门让人把飞机分拆包装，运回法国。","kind":"narration","speaker":"旁白"},{"en":"Now a group of enthusiasts are going to have the plane restored.","zh":"现在，一群爱好者准备请人修复这架飞机。","kind":"narration","speaker":"旁白"},{"en":"It has four Rolls-Royce Merlin engines, but the group will need to have only three of them rebuilt.","zh":"它有四台劳斯莱斯“梅林”发动机，但这群人只需要请人翻修其中三台。","kind":"narration","speaker":"旁白"},{"en":"Imagine their surprise and delight when they broke open the packing cases and found that the fourth engine was sweet as honey — still in perfect condition.","zh":"想象一下，当他们撬开包装箱，发现第四台发动机甜如蜂蜜，而且仍然完好无损时，是多么惊喜！","kind":"narration","speaker":"旁白"},{"en":"A colony of bees had turned the engine into a hive and it was totally preserved in beeswax!","zh":"一群蜜蜂把发动机变成了蜂巢，发动机被蜂蜡完整地保存了下来！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l067","number":67,"book":2,"title":"Volcanoes","paragraphs":[{"index":0,"rows":[{"en":"Haroun Tazieff, the Polish scientist, has spent his lifetime studying active volcanoes and deep caves in all parts of the world.","zh":"波兰科学家哈鲁恩·塔齐耶夫把一生都用来研究世界各地的活火山和深洞。","kind":"narration","speaker":"旁白"},{"en":"In 1948, he went to Lake Kivu in the Congo to observe a new volcano which he later named Kituro.","zh":"1948年，他前往刚果的基伍湖，观察一座新出现的火山，后来他把这座火山命名为基图罗。","kind":"narration","speaker":"旁白"},{"en":"Tazieff was able to set up his camp very close to the volcano while it was erupting violently.","zh":"塔齐耶夫在火山猛烈喷发时，竟能把营地扎在离火山很近的地方。","kind":"narration","speaker":"旁白"},{"en":"Though he managed to take a number of brilliant photographs, he could not stay near the volcano for very long.","zh":"虽然他设法拍到了许多精彩的照片，却无法在火山附近久留。","kind":"narration","speaker":"旁白"},{"en":"He noticed that a river of liquid rock was coming towards him.","zh":"他注意到，一股熔岩正像河流一样向他涌来。","kind":"narration","speaker":"旁白"},{"en":"It threatened to surround him completely, but Tazieff managed to escape just in time.","zh":"熔岩眼看就要把他完全包围，但塔齐耶夫设法及时逃了出去。","kind":"narration","speaker":"旁白"},{"en":"He waited until the volcano became quiet and he was able to return two days later.","zh":"他一直等到火山平静下来，两天后才得以返回。","kind":"narration","speaker":"旁白"},{"en":"This time, he managed to climb into the mouth of Kituro so that he could take photographs and measure temperatures.","zh":"这一次，他设法爬进了基图罗的火山口，以便拍照和测量温度。","kind":"narration","speaker":"旁白"},{"en":"Tazieff has often risked his life in this way.","zh":"塔齐耶夫经常这样冒着生命危险。","kind":"narration","speaker":"旁白"},{"en":"He has been able to tell us more about active volcanoes than any man alive.","zh":"关于活火山，他向我们提供的知识比任何在世的人都多。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l068","number":68,"book":2,"title":"Persistent","paragraphs":[{"index":0,"rows":[{"en":"I crossed the street to avoid meeting him, but he saw me and came running towards me.","zh":"我穿过马路，想避开他，可他看见了我，朝我跑了过来。","kind":"narration","speaker":"旁白"},{"en":"It was no use pretending that I had not seen him, so I waved to him.","zh":"假装没看见他已经没有用了，于是我向他挥了挥手。","kind":"narration","speaker":"旁白"},{"en":"I never enjoy meeting Nigel Dykes.","zh":"我从来都不喜欢遇到奈杰尔·戴克斯。","kind":"narration","speaker":"旁白"},{"en":"He never has anything to do.","zh":"他总是无事可做。","kind":"narration","speaker":"旁白"},{"en":"No matter how busy you are, he always insists on coming with you.","zh":"不管你有多忙，他总是坚持要跟着你。","kind":"narration","speaker":"旁白"},{"en":"I had to think of a way of preventing him from following me around all morning.","zh":"我得想个办法，免得他整个上午都跟在我身边。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘Hello, Nigel,’ I said.","zh":"“你好，奈杰尔，”我说。","kind":"speech","speaker":"伊丽莎白（我）"},{"en":"‘Fancy meeting you here!’","zh":"“真没想到在这里碰见你！”","kind":"speech","speaker":"伊丽莎白（我）"}]},{"index":2,"rows":[{"en":"‘Hi, Elizabeth,’ Nigel answered.","zh":"“嗨，伊丽莎白，”奈杰尔回答。","kind":"speech","speaker":"奈杰尔"},{"en":"‘I was just wondering how to spend the morning — until I saw you.","zh":"“刚才我还在琢磨这个上午该怎么过，直到我看见了你。","kind":"speech","speaker":"奈杰尔"},{"en":"You're not busy doing anything, are you?’","zh":"你没忙什么事吧？”","kind":"speech","speaker":"奈杰尔"}]},{"index":3,"rows":[{"en":"‘No, not at all,’ I answered.","zh":"“没有，一点也不忙，”我回答。","kind":"speech","speaker":"伊丽莎白（我）"},{"en":"‘I'm going to ...’","zh":"“我正要去……”","kind":"speech","speaker":"伊丽莎白（我）"}]},{"index":4,"rows":[{"en":"‘Would you mind my coming with you?’ he asked, before I had finished speaking.","zh":"我还没说完，他就问：“我跟你一起去，你介意吗？”","kind":"speech","speaker":"奈杰尔"}]},{"index":5,"rows":[{"en":"‘Not at all,’ I lied, ‘but I'm going to the dentist.’","zh":"“一点也不介意，”我撒谎说，“不过，我要去看牙医。”","kind":"speech","speaker":"伊丽莎白（我）"}]},{"index":6,"rows":[{"en":"‘Then I'll come with you,’ he answered.","zh":"“那我就跟你一起去，”他回答。","kind":"speech","speaker":"奈杰尔"},{"en":"‘There’s always plenty to read in the waiting room!’","zh":"“候诊室里总有很多东西可以看！”","kind":"speech","speaker":"奈杰尔"}]}]},{"lessonId":"nce-b2-eef57c-l069","number":69,"book":2,"title":"But not murder!","paragraphs":[{"index":0,"rows":[{"en":"I was being tested for a driving licence for the third time.","zh":"我正在第三次参加驾驶执照考试。","kind":"narration","speaker":"旁白"},{"en":"I had been asked to drive in heavy traffic and had done so successfully.","zh":"考官让我在车流繁忙的路段开车，我顺利地完成了。","kind":"narration","speaker":"旁白"},{"en":"After having been instructed to drive out of town, I began to acquire confidence.","zh":"接着，考官指示我把车开出城，我开始有了信心。","kind":"narration","speaker":"旁白"},{"en":"Sure that I had passed, I was almost beginning to enjoy my test.","zh":"我确信自己已经通过了，几乎开始享受这场考试了。","kind":"narration","speaker":"旁白"},{"en":"The examiner must have been pleased with my performance, for he smiled and said, ‘Just one more thing, Mr. Eames.","zh":"考官一定对我的表现很满意，因为他微笑着说：“就剩最后一项了，伊姆斯先生。","kind":"mixed","speaker":"旁白与考官","breakBefore":true},{"en":"Let us suppose that a child suddenly crosses the road in front of you.","zh":"假设有个孩子突然从你前面横穿马路。","kind":"speech","speaker":"考官","breakBefore":true},{"en":"As soon as I tap on the window, you must stop within five feet.’","zh":"我一敲车窗，你就必须在五英尺内把车停住。”","kind":"speech","speaker":"考官"},{"en":"I continued driving and after some time, the examiner tapped loudly.","zh":"我继续开车，过了一会儿，考官用力敲了敲车窗。","kind":"narration","speaker":"旁白","breakBefore":true},{"en":"Though the sound could be heard clearly, it took me a long time to react.","zh":"虽然声音听得很清楚，我却过了很久才反应过来。","kind":"narration","speaker":"旁白"},{"en":"I suddenly pressed the brake pedal hard and we were both thrown forward.","zh":"我突然用力踩下刹车踏板，我们俩都被向前甩了出去。","kind":"narration","speaker":"旁白"},{"en":"The examiner looked at me sadly.","zh":"考官难过地望着我。","kind":"narration","speaker":"旁白"},{"en":"‘Mr. Eames,’ he said, in a mournful voice, ‘you have just killed that child!’","zh":"“伊姆斯先生，”他用悲伤的语气说，“你刚才已经把那个孩子撞死了！”","kind":"speech","speaker":"考官","breakBefore":true}]}]},{"lessonId":"nce-b2-eef57c-l070","number":70,"book":2,"title":"Red for danger","paragraphs":[{"index":0,"rows":[{"en":"During a bullfight, a drunk suddenly wandered into the middle of the ring.","zh":"一场斗牛正在进行时，一个醉汉突然晃进了斗牛场中央。","kind":"narration","speaker":"旁白"},{"en":"The crowd began to shout, but the drunk was unaware of the danger.","zh":"观众开始大声叫喊，醉汉却没有意识到危险。","kind":"narration","speaker":"旁白"},{"en":"The bull was busy with the matador at the time, but it suddenly caught sight of the drunk who was shouting rude remarks and waving a red cap.","zh":"当时，公牛正忙着对付斗牛士，却突然看见那个醉汉一边骂骂咧咧，一边挥舞着一顶红帽子。","kind":"narration","speaker":"旁白"},{"en":"Apparently sensitive to criticism, the bull forgot all about the matador and charged at the drunk.","zh":"公牛似乎对批评十分敏感，把斗牛士全忘了，径直朝醉汉冲去。","kind":"narration","speaker":"旁白"},{"en":"The crowd suddenly grew quiet.","zh":"观众突然安静下来。","kind":"narration","speaker":"旁白"},{"en":"The drunk, however, seemed quite sure of himself.","zh":"然而，醉汉似乎对自己十分有把握。","kind":"narration","speaker":"旁白"},{"en":"When the bull got close to him, he clumsily stepped aside to let it pass.","zh":"公牛冲到他跟前时，他笨拙地往旁边一闪，让公牛冲了过去。","kind":"narration","speaker":"旁白"},{"en":"The crowd broke into cheers and the drunk bowed.","zh":"观众爆发出欢呼，醉汉鞠了一躬。","kind":"narration","speaker":"旁白"},{"en":"By this time, however, three men had come into the ring and they quickly dragged the drunk to safety.","zh":"不过这时，已有三个人进了斗牛场，他们迅速把醉汉拖到了安全的地方。","kind":"narration","speaker":"旁白"},{"en":"Even the bull seemed to feel sorry for him, for it looked on sympathetically until the drunk was out of the way before once more turning its attention to the matador.","zh":"连公牛似乎也替他感到遗憾，因为它一直带着同情的神情望着醉汉，等他离开以后，才再次把注意力转回斗牛士。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l071","number":71,"book":2,"title":"A famous clock","paragraphs":[{"index":0,"rows":[{"en":"When you visit London, one of the first things you will see is Big Ben, the famous clock which can be heard all over the world on the B.B.C.","zh":"到伦敦游览时，你最先看到的景物之一就是著名的大本钟，世界各地的人们都能通过英国广播公司听到它的钟声。","kind":"narration","speaker":"旁白"},{"en":"If the Houses of Parliament had not been burned down in 1834, the great clock would never have been erected.","zh":"要不是议会大厦在1834年被烧毁，这座大钟本来就不会建造。","kind":"narration","speaker":"旁白"},{"en":"Big Ben takes its name from Sir Benjamin Hall who was responsible for the making of the clock when the new Houses of Parliament were being built.","zh":"大本钟以本杰明·霍尔爵士的名字命名，新议会大厦兴建时，他负责监造这座大钟。","kind":"narration","speaker":"旁白"},{"en":"It is not only of immense size, but is extremely accurate as well.","zh":"它不仅体积巨大，而且走时极其准确。","kind":"narration","speaker":"旁白"},{"en":"Officials from Greenwich Observatory have the clock checked twice a day.","zh":"格林尼治天文台的工作人员每天请人校对这座钟两次。","kind":"narration","speaker":"旁白"},{"en":"On the B.B.C. you can hear the clock when it is actually striking because microphones are connected to the clock tower.","zh":"你可以通过英国广播公司实时听到大钟报时，因为麦克风与钟楼相连。","kind":"narration","speaker":"旁白"},{"en":"Big Ben has rarely gone wrong.","zh":"大本钟极少出差错。","kind":"narration","speaker":"旁白"},{"en":"Once, however, it failed to give the correct time.","zh":"不过，有一次它没能报出准确的时间。","kind":"narration","speaker":"旁白"},{"en":"A painter who had been working on the tower hung a pot of paint on one of the hands and slowed it down!","zh":"一位在钟楼上干活的油漆工把一罐油漆挂在了一根指针上，使钟走慢了！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l072","number":72,"book":2,"title":"A car called Bluebird","paragraphs":[{"index":0,"rows":[{"en":"The great racing driver, Sir Malcolm Campbell, was the first man to drive at over 300 miles per hour.","zh":"著名赛车手马尔科姆·坎贝尔爵士，是第一个把车开到时速超过三百英里的人。","kind":"narration","speaker":"旁白"},{"en":"He set up a new world record in September 1935 at Bonneville Salt Flats, Utah.","zh":"1935年9月，他在犹他州的邦纳维尔盐滩创下了新的世界纪录。","kind":"narration","speaker":"旁白"},{"en":"Bluebird, the car he was driving, had been specially built for him.","zh":"他驾驶的那辆名叫“蓝鸟”的汽车，是专门为他制造的。","kind":"narration","speaker":"旁白"},{"en":"It was over 30 feet in length and had a 2,500-horsepower engine.","zh":"它的车长超过三十英尺，装有一台两千五百马力的发动机。","kind":"narration","speaker":"旁白"},{"en":"Although Campbell reached a speed of over 304 miles per hour, he had great difficulty in controlling the car because a tyre burst during the first run.","zh":"虽然坎贝尔达到了每小时三百零四英里以上的速度，但由于第一次试跑时有一只轮胎爆裂，他很难控制住汽车。","kind":"narration","speaker":"旁白"},{"en":"After his attempt, Campbell was disappointed to learn that his average speed had been 299 miles per hour.","zh":"尝试过后，坎贝尔得知自己的平均时速为二百九十九英里，十分失望。","kind":"narration","speaker":"旁白"},{"en":"However, a few days later, he was told that a mistake had been made.","zh":"然而，几天后，有人告诉他，先前弄错了。","kind":"narration","speaker":"旁白"},{"en":"His average speed had been 301 miles per hour.","zh":"他的平均时速其实是三百零一英里。","kind":"narration","speaker":"旁白"},{"en":"Since that time, racing drivers have reached speeds over 600 miles an hour.","zh":"从那以后，赛车手们已经达到了每小时六百英里以上的速度。","kind":"narration","speaker":"旁白"},{"en":"Following in his father’s footsteps many years later, Sir Malcolm's son, Donald, also set up a world record.","zh":"多年后，马尔科姆爵士的儿子唐纳德追随父亲的脚步，也创下了一项世界纪录。","kind":"narration","speaker":"旁白"},{"en":"Like his father, he was driving a car called Bluebird.","zh":"和父亲一样，他驾驶的汽车也叫“蓝鸟”。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l073","number":73,"book":2,"title":"The record-holder","paragraphs":[{"index":0,"rows":[{"en":"Children who play truant from school are unimaginative.","zh":"逃学的孩子缺乏想象力。","kind":"narration","speaker":"旁白"},{"en":"A quiet day's fishing, or eight hours in a cinema seeing the same film over and over again, is usually as far as they get.","zh":"安安静静钓一天鱼，或是在电影院里待八个小时，把同一部电影看上一遍又一遍，通常就是他们所能想到的最大花样了。","kind":"narration","speaker":"旁白"},{"en":"They have all been put to shame by a boy who, while playing truant, travelled 1,600 miles.","zh":"一个男孩在逃学期间旅行了一千六百英里，让他们全都相形见绌。","kind":"narration","speaker":"旁白"},{"en":"He hitchhiked to Dover and, towards evening, went into a boat to find somewhere to sleep.","zh":"他搭便车到了多佛，傍晚时走上一条船，想找个地方睡觉。","kind":"narration","speaker":"旁白"},{"en":"When he woke up next morning, he discovered that the boat had, in the meantime, travelled to Calais.","zh":"第二天早晨醒来时，他发现船已经在这期间驶到了加来。","kind":"narration","speaker":"旁白"},{"en":"No one noticed the boy as he crept off.","zh":"男孩偷偷溜下船时，没有人注意到他。","kind":"narration","speaker":"旁白"},{"en":"From there, he hitchhiked to Paris in a lorry.","zh":"从那里，他搭上一辆卡车前往巴黎。","kind":"narration","speaker":"旁白"},{"en":"The driver gave him a few biscuits and a cup of coffee and left him just outside the city.","zh":"司机给了他几块饼干和一杯咖啡，把他留在巴黎城外不远的地方。","kind":"narration","speaker":"旁白"},{"en":"The next car the boy stopped did not take him into the centre of Paris as he hoped it would, but to Perpignan on the French-Spanish border.","zh":"男孩接着拦下的那辆车，并没有像他希望的那样把他带进巴黎市中心，而是把他带到了法西边境上的佩皮尼昂。","kind":"narration","speaker":"旁白"},{"en":"There he was picked up by a policeman and sent back to England by the local authorities.","zh":"在那里，他被一名警察带走，又由当地有关部门送回英国。","kind":"narration","speaker":"旁白"},{"en":"He has surely set up a record for the thousands of children who dream of evading school.","zh":"他无疑为成千上万梦想逃学的孩子创下了一项纪录。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l074","number":74,"book":2,"title":"Out of the limelight","paragraphs":[{"index":0,"rows":[{"en":"An ancient bus stopped by a dry river bed and a party of famous actors and actresses got off.","zh":"一辆破旧的公共汽车停在一条干涸的河床旁，一群著名的男女演员下了车。","kind":"narration","speaker":"旁白"},{"en":"Dressed in dark glasses and old clothes, they had taken special precautions so that no one should recognize them.","zh":"他们戴着墨镜，穿着旧衣服，特意采取了防范措施，免得有人认出他们。","kind":"narration","speaker":"旁白"},{"en":"But as they soon discovered, disguises can sometimes be too perfect.","zh":"不过，他们很快就发现，有时伪装也会太成功。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘This is a wonderful place for a picnic,’ said Gloria Gleam.","zh":"“这里真是个野餐的好地方，”格洛丽亚·格利姆说。","kind":"speech","speaker":"格洛丽亚·格利姆"}]},{"index":2,"rows":[{"en":"‘It couldn’t be better, Gloria,’ Brinksley Meers agreed.","zh":"“再好不过了，格洛丽亚，”布林克斯利·米尔斯赞同道。","kind":"speech","speaker":"布林克斯利·米尔斯"},{"en":"‘No newspaper men, no film fans!","zh":"“没有记者，也没有影迷！","kind":"speech","speaker":"布林克斯利·米尔斯"},{"en":"Why don’t we come more often?’","zh":"我们为什么不常来呢？”","kind":"speech","speaker":"布林克斯利·米尔斯"}]},{"index":3,"rows":[{"en":"Meanwhile, two other actors, Rockwall Slinger and Merlin Greeves, had carried two large food baskets to a shady spot under some trees.","zh":"与此同时，另外两名演员罗克沃尔·斯林格和默林·格里夫斯，已经把两大篮食物搬到了几棵树下的阴凉处。","kind":"narration","speaker":"旁白"},{"en":"When they had all made themselves comfortable, a stranger appeared.","zh":"大家刚舒舒服服地安顿下来，一个陌生人就出现了。","kind":"narration","speaker":"旁白"},{"en":"He looked very angry.","zh":"他看起来非常生气。","kind":"narration","speaker":"旁白"},{"en":"‘Now you get out of here, all of you!’ he shouted.","zh":"“现在，你们全都给我离开这里！”他大声喊道。","kind":"speech","speaker":"警长","breakBefore":true},{"en":"‘I'm sheriff here.","zh":"“我是这里的警长。","kind":"speech","speaker":"警长"},{"en":"Do you see that notice?","zh":"看见那块告示了吗？","kind":"speech","speaker":"警长"},{"en":"It says “No Camping” — in case you can’t read!’","zh":"上面写着‘禁止露营’——我怕你们不识字，特意告诉你们！”","kind":"speech","speaker":"警长"}]},{"index":4,"rows":[{"en":"‘Look, sheriff,’ said Rockwall, ‘don’t be too hard on us.","zh":"“听我说，警长，”罗克沃尔说，“别对我们这么严厉。","kind":"speech","speaker":"罗克沃尔·斯林格"},{"en":"I'm Rockwall Slinger and this is Merlin Greeves.’","zh":"我是罗克沃尔·斯林格，这位是默林·格里夫斯。”","kind":"speech","speaker":"罗克沃尔·斯林格"}]},{"index":5,"rows":[{"en":"‘Oh, is it?’ said the sheriff with a sneer.","zh":"“哦，是吗？”警长冷笑着说。","kind":"speech","speaker":"警长"},{"en":"‘Well, I'm Brinksley Meers, and my other name is Gloria Gleam.","zh":"“那么，我就是布林克斯利·米尔斯，我还有个名字叫格洛丽亚·格利姆。","kind":"speech","speaker":"警长"},{"en":"Now you get out of here fast!’","zh":"现在，你们赶快给我走！”","kind":"speech","speaker":"警长"}]}]},{"lessonId":"nce-b2-eef57c-l075","number":75,"book":2,"title":"SOS","paragraphs":[{"index":0,"rows":[{"en":"When a light passenger plane flew off course some time ago, it crashed in the mountains and its pilot was killed.","zh":"前些时候，一架轻型客机偏离航线，坠毁在山区，飞行员丧生了。","kind":"narration","speaker":"旁白"},{"en":"The only passengers, a young woman and her two baby daughters, were unhurt.","zh":"机上仅有的乘客是一名年轻女子和她的两个年幼女儿，她们都没有受伤。","kind":"narration","speaker":"旁白"},{"en":"It was the middle of winter.","zh":"当时正值隆冬。","kind":"narration","speaker":"旁白"},{"en":"Snow lay thick on the ground.","zh":"地上积着厚厚的雪。","kind":"narration","speaker":"旁白"},{"en":"The woman knew that the nearest village was miles away.","zh":"那名女子知道，最近的村庄也在数英里以外。","kind":"narration","speaker":"旁白"},{"en":"When it grew dark, she turned a suitcase into a bed and put the children inside it, covering them with all the clothes she could find.","zh":"天黑下来时，她把一只手提箱当作床，把孩子们放进里面，再把能找到的所有衣服都盖在她们身上。","kind":"narration","speaker":"旁白"},{"en":"During the night, it got terribly cold.","zh":"夜里，天气冷得厉害。","kind":"narration","speaker":"旁白"},{"en":"The woman kept as near as she could to the children and even tried to get into the case herself, but it was too small.","zh":"那名女子尽可能地紧挨着孩子们，甚至试图自己也钻进箱子，但箱子太小了。","kind":"narration","speaker":"旁白"},{"en":"Early next morning, she heard planes passing overhead and wondered how she could send a signal.","zh":"第二天一早，她听到飞机从头顶飞过，琢磨着怎样才能发出信号。","kind":"narration","speaker":"旁白"},{"en":"Then she had an idea.","zh":"接着，她有了一个主意。","kind":"narration","speaker":"旁白"},{"en":"She stamped out the letters ‘SOS’ in the snow.","zh":"她在雪地里踩出了“SOS”这几个字母。","kind":"narration","speaker":"旁白"},{"en":"Fortunately, a pilot saw the signal and sent a message by radio to the nearest town.","zh":"幸运的是，一名飞行员看见了这个信号，用无线电把消息发给了最近的城镇。","kind":"narration","speaker":"旁白"},{"en":"It was not long before a helicopter arrived on the scene to rescue the survivors of the plane crash.","zh":"没过多久，一架直升机就赶到现场，营救这次空难的幸存者。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l076","number":76,"book":2,"title":"April Fools’ Day","paragraphs":[{"index":0,"rows":[{"en":"‘To end our special news bulletin,’ said the voice of the television announcer, ‘we're going over to the macaroni fields of Calabria.","zh":"“在本次特别新闻简报结束之前，”电视播音员的声音说道，“我们把镜头转到卡拉布里亚的通心粉田。","kind":"speech","speaker":"电视播音员"},{"en":"Macaroni has been grown in this area for over six hundred years.","zh":"这个地区种植通心粉已经有六百多年了。","kind":"speech","speaker":"电视播音员"},{"en":"Two of the leading growers, Giuseppe Moldova and Riccardo Brabante, tell me that they have been expecting a splendid crop this year and harvesting has begun earlier than usual.","zh":"两位主要种植户朱塞佩·摩尔多瓦和里卡尔多·布拉班特告诉我，他们一直盼望今年获得大丰收，收割也比往年提早开始了。","kind":"speech","speaker":"电视播音员"},{"en":"Here you can see two workers who, between them, have just finished cutting three cartloads of golden brown macaroni stalks.","zh":"这里可以看到两位工人，他们俩刚刚合力割下了三车金棕色的通心粉秆。","kind":"speech","speaker":"电视播音员"},{"en":"The whole village has been working day and night gathering and threshing this year’s crop before the September rains.","zh":"全村的人一直在日夜忙碌，赶在九月的雨季来临之前，收割、脱粒今年的作物。","kind":"speech","speaker":"电视播音员"},{"en":"On the right, you can see Mrs. Brabante herself.","zh":"右边可以看到布拉班特夫人本人。","kind":"speech","speaker":"电视播音员"},{"en":"She has been helping her husband for thirty years now.","zh":"到现在，她已经帮丈夫干了三十年了。","kind":"speech","speaker":"电视播音员"},{"en":"Mrs. Brabante is talking to the manager of the local factory where the crop is processed.","zh":"布拉班特夫人正在同当地一家工厂的经理谈话，收下的作物就在那家工厂加工。","kind":"speech","speaker":"电视播音员"},{"en":"This last scene shows you what will happen at the end of the harvest: the famous Calabrian macaroni-eating competition!","zh":"最后这个场景向大家展示收获结束时将举行的活动：著名的卡拉布里亚吃通心粉比赛！","kind":"speech","speaker":"电视播音员"},{"en":"Signor Fratelli, the present champion, has won it every year since 1991.","zh":"现任冠军弗拉特利先生从1991年以来，每年都赢得这项比赛。","kind":"speech","speaker":"电视播音员"},{"en":"And that ends our special bulletin for today, Thursday, April 1st.","zh":"今天是4月1日，星期四，我们的特别新闻简报到此结束。","kind":"speech","speaker":"电视播音员"},{"en":"We're now going back to the studio.’","zh":"现在我们把画面交回演播室。”","kind":"speech","speaker":"电视播音员"}]}]},{"lessonId":"nce-b2-eef57c-l077","number":77,"book":2,"title":"A successful operation","paragraphs":[{"index":0,"rows":[{"en":"The mummy of an Egyptian woman who died in 800 B.C. has just had an operation.","zh":"一具属于公元前800年去世的埃及妇女的木乃伊，刚刚接受了一次手术。","kind":"narration","speaker":"旁白"},{"en":"The mummy is that of Shepenmut who was once a singer in the Temple of Thebes.","zh":"这具木乃伊属于谢彭穆特，她曾是底比斯神庙的一名歌者。","kind":"narration","speaker":"旁白"},{"en":"As there were strange marks on the X-ray plates taken of the mummy, doctors have been trying to find out whether the woman died of a rare disease.","zh":"由于给木乃伊拍摄的X光片上有一些奇怪的斑痕，医生们一直想查明，这名妇女是否死于一种罕见疾病。","kind":"narration","speaker":"旁白"},{"en":"The only way to do this was to operate.","zh":"要弄清这一点，唯一的办法就是动手术。","kind":"narration","speaker":"旁白"},{"en":"The operation, which lasted for over four hours, proved to be very difficult because of the hard resin which covered the skin.","zh":"手术持续了四个多小时，由于皮肤上覆盖着坚硬的树脂，手术十分困难。","kind":"narration","speaker":"旁白"},{"en":"The doctors removed a section of the mummy and sent it to a laboratory.","zh":"医生们从木乃伊上取下一部分，送到了一家实验室。","kind":"narration","speaker":"旁白"},{"en":"They also found something which the X-ray plates did not show: a small wax figure of the god Duamutef.","zh":"他们还发现了一件X光片没有显示的东西：一尊小小的杜阿姆特夫神蜡像。","kind":"narration","speaker":"旁白"},{"en":"This god which has the head of a cow was normally placed inside a mummy.","zh":"这个长着牛头的神的塑像，通常被放在木乃伊体内。","kind":"narration","speaker":"旁白"},{"en":"The doctors have not yet decided how the woman died.","zh":"医生们还没有确定这名妇女的死因。","kind":"narration","speaker":"旁白"},{"en":"They feared that the mummy would fall to pieces when they cut it open, but fortunately this has not happened.","zh":"他们原来担心，剖开木乃伊时，它会碎成片片，不过幸运的是，这种情况并没有发生。","kind":"narration","speaker":"旁白"},{"en":"The mummy successfully survived the operation.","zh":"这具木乃伊成功地经受住了手术。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l078","number":78,"book":2,"title":"The last one?","paragraphs":[{"index":0,"rows":[{"en":"After reading an article entitled ‘Cigarette Smoking and Your Health’ I lit a cigarette to calm my nerves.","zh":"读完一篇题为《吸烟与你的健康》的文章后，我点起一支烟，让自己镇定下来。","kind":"narration","speaker":"旁白"},{"en":"I smoked with concentration and pleasure as I was sure that this would be my last cigarette.","zh":"我专心而愉快地抽着，因为我确信这将是自己的最后一支烟。","kind":"narration","speaker":"旁白"},{"en":"For a whole week I did not smoke at all and during this time, my wife suffered terribly.","zh":"整整一个星期，我一支烟也没抽，在这期间，我妻子可受了大罪。","kind":"narration","speaker":"旁白"},{"en":"I had all the usual symptoms of someone giving up smoking: a bad temper and an enormous appetite.","zh":"我出现了戒烟者常有的各种症状：脾气暴躁，胃口大得惊人。","kind":"narration","speaker":"旁白"},{"en":"My friends kept on offering me cigarettes and cigars.","zh":"朋友们不停地给我递香烟和雪茄。","kind":"narration","speaker":"旁白"},{"en":"They made no effort to hide their amusement whenever I produced a packet of sweets from my pocket.","zh":"每当我从口袋里掏出一包糖果时，他们都毫不掩饰自己觉得好笑。","kind":"narration","speaker":"旁白"},{"en":"After seven days of this I went to a party.","zh":"这样过了七天后，我去参加了一次聚会。","kind":"narration","speaker":"旁白"},{"en":"Everybody around me was smoking and I felt extremely uncomfortable.","zh":"周围人人都在吸烟，我觉得浑身不自在。","kind":"narration","speaker":"旁白"},{"en":"When my old friend Brian urged me to accept a cigarette, it was more than I could bear.","zh":"老朋友布赖恩劝我拿一支烟时，我再也抵挡不住了。","kind":"narration","speaker":"旁白"},{"en":"I took one guiltily, lit it and smoked with satisfaction.","zh":"我心虚地接过一支，点上后心满意足地抽了起来。","kind":"narration","speaker":"旁白"},{"en":"My wife was delighted that things had returned to normal once more.","zh":"一切又恢复了正常，妻子十分高兴。","kind":"narration","speaker":"旁白"},{"en":"Anyway, as Brian pointed out, it is the easiest thing in the world to give up smoking.","zh":"不管怎么说，正如布赖恩指出的，戒烟是世界上最容易的事。","kind":"narration","speaker":"旁白"},{"en":"He himself has done it lots of times!","zh":"他自己就已经戒过很多次了！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l079","number":79,"book":2,"title":"By air","paragraphs":[{"index":0,"rows":[{"en":"I used to travel by air a great deal when I was a boy.","zh":"小时候，我常常乘飞机旅行。","kind":"narration","speaker":"旁白"},{"en":"My parents used to live in South America and I used to fly there from Europe in the holidays.","zh":"父母那时住在南美洲，放假时，我便从欧洲乘飞机去那里。","kind":"narration","speaker":"旁白"},{"en":"A flight attendant would take charge of me and I never had an unpleasant experience.","zh":"总有一名乘务员照看我，我从未有过不愉快的经历。","kind":"narration","speaker":"旁白"},{"en":"I am used to travelling by air and only on one occasion have I ever felt frightened.","zh":"我已经习惯乘飞机旅行，只有一次感到过害怕。","kind":"narration","speaker":"旁白"},{"en":"After taking off, we were flying low over the city and slowly gaining height, when the plane suddenly turned round and flew back to the airport.","zh":"起飞以后，飞机低低地飞过城市，正在慢慢爬升，突然掉头飞回了机场。","kind":"narration","speaker":"旁白"},{"en":"While we were waiting to land, a flight attendant told us to keep calm and to get off the plane quietly as soon as it had touched down.","zh":"等候降落时，一名乘务员让我们保持镇静，飞机一着陆就安静地下机。","kind":"narration","speaker":"旁白"},{"en":"Everybody on board was worried and we were curious to find out what had happened.","zh":"机上人人都很担心，我们都急于知道发生了什么事。","kind":"narration","speaker":"旁白"},{"en":"Later we learnt that there was a very important person on board.","zh":"后来我们才知道，机上有一位非常重要的人物。","kind":"narration","speaker":"旁白"},{"en":"The police had been told that a bomb had been planted on the plane.","zh":"警方接到消息，说有人在飞机上放了炸弹。","kind":"narration","speaker":"旁白"},{"en":"After we had landed, the plane was searched thoroughly.","zh":"我们着陆后，飞机接受了彻底搜查。","kind":"narration","speaker":"旁白"},{"en":"Fortunately, nothing was found and five hours later we were able to take off again.","zh":"幸运的是，什么也没有发现，五个小时后，我们得以再次起飞。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l080","number":80,"book":2,"title":"The Crystal Palace","paragraphs":[{"index":0,"rows":[{"en":"Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851.","zh":"十九世纪最不同寻常的建筑，也许就是水晶宫；它是为1851年的万国博览会而建在海德公园里的。","kind":"narration","speaker":"旁白"},{"en":"The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass.","zh":"水晶宫不同于世界上其他所有建筑，因为它是用铁和玻璃建成的。","kind":"narration","speaker":"旁白"},{"en":"It was one of the biggest buildings of all time and a lot of people from many countries came to see it.","zh":"它是有史以来规模最大的建筑之一，许多国家的大批游客都来参观。","kind":"narration","speaker":"旁白"},{"en":"A great many goods were sent to the exhibition from various parts of the world.","zh":"世界各地的大量商品被运来参展。","kind":"narration","speaker":"旁白"},{"en":"There was also a great deal of machinery on display.","zh":"现场还陈列着大量机器。","kind":"narration","speaker":"旁白"},{"en":"The most wonderful piece of machinery on show was Nasmyth’s steam hammer.","zh":"展出的机器中，最令人赞叹的是内史密斯的蒸汽锤。","kind":"narration","speaker":"旁白"},{"en":"Though in those days, travelling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe.","zh":"尽管那时旅行不像今天这样方便，汽船仍载着成千上万的游客从欧洲横渡英吉利海峡而来。","kind":"narration","speaker":"旁白"},{"en":"On arriving in England, they were taken to the Crystal Palace by train.","zh":"他们一到英国，就被火车送往水晶宫。","kind":"narration","speaker":"旁白"},{"en":"There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges.","zh":"参观者总计有六百万人，博览会的利润被用来建造博物馆和学院。","kind":"narration","speaker":"旁白"},{"en":"Later, the Crystal Palace was moved to South London.","zh":"后来，水晶宫被迁到了伦敦南部。","kind":"narration","speaker":"旁白"},{"en":"It remained one of the most famous buildings in the world until it was burnt down in 1936.","zh":"在1936年被大火烧毁以前，它一直是世界上最著名的建筑之一。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l081","number":81,"book":2,"title":"Escape","paragraphs":[{"index":0,"rows":[{"en":"When he had killed the guard, the prisoner of war quickly dragged him into the bushes.","zh":"那名战俘杀死卫兵后，迅速把他拖进了灌木丛。","kind":"narration","speaker":"旁白"},{"en":"Working rapidly in the darkness, he soon changed into the dead man’s clothes.","zh":"他在黑暗中飞快地行动，很快就换上了死者的衣服。","kind":"narration","speaker":"旁白"},{"en":"Now, dressed in a blue uniform and with a rifle over his shoulder, the prisoner marched boldly up and down in front of the camp.","zh":"此时，他身穿蓝色制服，肩扛一支步枪，大模大样地在营地前来回走动。","kind":"narration","speaker":"旁白"},{"en":"He could hear shouting in the camp itself.","zh":"他能听见营地里面的喊叫声。","kind":"narration","speaker":"旁白"},{"en":"Lights were blazing and men were running here and there: they had just discovered that a prisoner had escaped.","zh":"那里灯火通明，人们四处奔跑：他们刚刚发现有一名战俘逃走了。","kind":"narration","speaker":"旁白"},{"en":"At that moment, a large black car with four officers inside it, stopped at the camp gates.","zh":"就在这时，一辆黑色大轿车停在营地门口，里面坐着四名军官。","kind":"narration","speaker":"旁白"},{"en":"The officers got out and the prisoner stood to attention and saluted as they passed.","zh":"军官们下了车，经过战俘面前时，他立正敬礼。","kind":"narration","speaker":"旁白"},{"en":"When they had gone, the driver of the car came towards him.","zh":"等他们走后，汽车司机朝他走了过来。","kind":"narration","speaker":"旁白"},{"en":"The man obviously wanted to talk.","zh":"这个人显然想聊几句。","kind":"narration","speaker":"旁白"},{"en":"He was rather elderly with grey hair and clear blue eyes.","zh":"他年纪已经不小，头发灰白，有一双清澈的蓝眼睛。","kind":"narration","speaker":"旁白"},{"en":"The prisoner felt sorry for him, but there was nothing else he could do.","zh":"战俘心里有些同情他，却也别无选择。","kind":"narration","speaker":"旁白"},{"en":"As the man came near, the prisoner knocked him to the ground with a sharp blow.","zh":"那个人刚走近，战俘便猛击一下，把他打倒在地。","kind":"narration","speaker":"旁白"},{"en":"Then, jumping into the car, he drove off as quickly as he could.","zh":"随后，战俘跳上汽车，以最快的速度开走了。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l082","number":82,"book":2,"title":"Monster or fish?","paragraphs":[{"index":0,"rows":[{"en":"Fishermen and sailors sometimes claim to have seen monsters in the sea.","zh":"渔民和水手有时声称见过海里的怪物。","kind":"narration","speaker":"旁白"},{"en":"Though people have often laughed at stories told by seamen, it is now known that many of these ‘monsters’ which have at times been sighted are simply strange fish.","zh":"虽然人们常常嘲笑海员讲的这些故事，但现在已经知道，这些时而被人目击的“怪物”，许多只不过是奇特的鱼。","kind":"narration","speaker":"旁白"},{"en":"Occasionally, unusual creatures are washed to the shore, but they are rarely caught out at sea.","zh":"偶尔会有不寻常的生物被冲到岸上，但人们很少能在外海捕获它们。","kind":"narration","speaker":"旁白"},{"en":"Some time ago, however, a peculiar fish was caught near Madagascar.","zh":"不过，前些时候，人们在马达加斯加附近捕到了一条奇鱼。","kind":"narration","speaker":"旁白"},{"en":"A small fishing boat was carried miles out to sea by the powerful fish as it pulled on the line.","zh":"这条力大无比的鱼拽着钓线，把一条小渔船拖到了数英里外的海中。","kind":"narration","speaker":"旁白"},{"en":"Realizing that this was no ordinary fish, the fisherman made every effort not to damage it in any way.","zh":"渔夫意识到这不是一条普通的鱼，于是竭力避免以任何方式伤害它。","kind":"narration","speaker":"旁白"},{"en":"When it was eventually brought to shore, it was found to be over thirteen feet long.","zh":"等鱼终于被运到岸上，人们发现它有十三英尺多长。","kind":"narration","speaker":"旁白"},{"en":"It had a head like a horse, big blue eyes, shining silver skin, and a bright red tail.","zh":"它的头长得像马，有一双蓝色的大眼睛，银色的皮肤闪闪发亮，还有一条鲜红的尾巴。","kind":"narration","speaker":"旁白"},{"en":"The fish, which has since been sent to a museum where it is being examined by a scientist, is called an oarfish.","zh":"这种鱼叫皇带鱼，后来被送进了一家博物馆，正在那里由一名科学家研究。","kind":"narration","speaker":"旁白"},{"en":"Such creatures have rarely been seen alive by man as they live at a depth of six hundred feet.","zh":"这类生物生活在六百英尺深的海中，因此人类极少见到它们活着的样子。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l083","number":83,"book":2,"title":"After the elections","paragraphs":[{"index":0,"rows":[{"en":"The former Prime Minister, Mr. Wentworth Lane, was defeated in the recent elections.","zh":"前首相温特沃思·莱恩先生在最近的选举中落败了。","kind":"narration","speaker":"旁白"},{"en":"He is now retiring from political life and has gone abroad.","zh":"他现在正退出政治生活，并且已经去了国外。","kind":"narration","speaker":"旁白"},{"en":"My friend, Patrick, has always been a fanatical opponent of Mr. Lane's Radical Progressive Party.","zh":"我的朋友帕特里克，一向是莱恩先生的激进进步党的狂热反对者。","kind":"narration","speaker":"旁白"},{"en":"After the elections, Patrick went to the former Prime Minister's house.","zh":"选举结束后，帕特里克去了前首相家。","kind":"narration","speaker":"旁白"},{"en":"When he asked if Mr. Lane lived there, the policeman on duty told him that since his defeat, the ex-Prime Minister had gone abroad.","zh":"他问莱恩先生是否住在那里，值班警察告诉他，前首相自从败选以后就去了国外。","kind":"narration","speaker":"旁白"},{"en":"On the following day, Patrick went to the house again.","zh":"第二天，帕特里克又去了那所房子。","kind":"narration","speaker":"旁白"},{"en":"The same policeman was just walking slowly past the entrance, when Patrick asked the same question.","zh":"同一名警察正从门口慢慢走过，这时帕特里克又问了同样的问题。","kind":"narration","speaker":"旁白"},{"en":"Though a little suspicious this time, the policeman gave him the same answer.","zh":"这一次，警察虽然有些起疑，仍给了他同样的回答。","kind":"narration","speaker":"旁白"},{"en":"The day after, Patrick went to the house once more and asked exactly the same question.","zh":"又过了一天，帕特里克再次来到那所房子前，问了完全一样的问题。","kind":"narration","speaker":"旁白"},{"en":"This time, the policeman lost his temper.","zh":"这回，警察发火了。","kind":"narration","speaker":"旁白"},{"en":"‘I told you yesterday and the day before yesterday,’ he shouted, ‘Mr. Lane was defeated in the elections.","zh":"“我昨天和前天都告诉你了，”他大声喊道，“莱恩先生在选举中落败了。","kind":"speech","speaker":"警察","breakBefore":true},{"en":"He has retired from political life and gone to live abroad!’","zh":"他已经退出政坛，到国外居住去了！”","kind":"speech","speaker":"警察"}]},{"index":1,"rows":[{"en":"‘I know,’ answered Patrick, ‘but I love to hear you say it!’","zh":"“我知道，”帕特里克回答，“可我就是喜欢听你这样说！”","kind":"speech","speaker":"帕特里克"}]}]},{"lessonId":"nce-b2-eef57c-l084","number":84,"book":2,"title":"On strike.","paragraphs":[{"index":0,"rows":[{"en":"Busmen have decided to go on strike next week.","zh":"公共汽车职工们决定下周罢工。","kind":"narration","speaker":"旁白"},{"en":"The strike is due to begin on Tuesday.","zh":"罢工定于星期二开始。","kind":"narration","speaker":"旁白"},{"en":"No one knows how long it will last.","zh":"没有人知道罢工会持续多久。","kind":"narration","speaker":"旁白"},{"en":"The busmen have stated that the strike will continue until general agreement is reached about pay and working conditions.","zh":"公共汽车职工们声明，罢工将持续到大家就工资和工作条件达成一致为止。","kind":"narration","speaker":"旁白"},{"en":"Most people believe that the strike will last for at least a week.","zh":"大多数人认为，这次罢工至少会持续一周。","kind":"narration","speaker":"旁白"},{"en":"Many owners of private cars are going to offer ‘free rides’ to people on their way to work.","zh":"许多私家车车主打算为上班途中的人提供“免费搭车”的便利。","kind":"narration","speaker":"旁白"},{"en":"This will relieve pressure on the trains to some extent.","zh":"这将在一定程度上减轻火车的压力。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, a number of university students have volunteered to drive buses while the strike lasts.","zh":"与此同时，一些大学生自愿在罢工期间驾驶公共汽车。","kind":"narration","speaker":"旁白"},{"en":"All the students are expert drivers, but before they drive any of the buses, they will have to pass a special test.","zh":"这些学生都很擅长开车，但在驾驶任何一辆公共汽车之前，都必须通过一项专门考试。","kind":"narration","speaker":"旁白"},{"en":"The students are going to take the test in two days’ time.","zh":"学生们将在两天后参加考试。","kind":"narration","speaker":"旁白"},{"en":"Even so, people are going to find it difficult to get to work.","zh":"即便如此，人们还是会发现上班很困难。","kind":"narration","speaker":"旁白"},{"en":"But so far, the public has expressed its gratitude to the students in letters to the Press.","zh":"不过到目前为止，公众已经通过给报社写信，表达了对学生们的感谢。","kind":"narration","speaker":"旁白"},{"en":"Only one or two people have objected that the students will drive too fast!","zh":"只有一两个人提出异议，说学生们会把车开得太快！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l085","number":85,"book":2,"title":"Never too old to learn","paragraphs":[{"index":0,"rows":[{"en":"I have just received a letter from my old school, informing me that my former headmaster, Mr. Stuart Page, will be retiring next week.","zh":"我刚收到母校的一封信，通知我以前的校长斯图尔特·佩奇先生将于下周退休。","kind":"narration","speaker":"旁白"},{"en":"Pupils of the school, old and new, will be sending him a present to mark the occasion.","zh":"学校的新老学生将送给他一份礼物，以纪念这个时刻。","kind":"narration","speaker":"旁白"},{"en":"All those who have contributed towards the gift will sign their names in a large album which will be sent to the headmaster’s home.","zh":"所有捐钱购买礼物的人，都将在一本大纪念册上签名，这本纪念册将送到校长家中。","kind":"narration","speaker":"旁白"},{"en":"We shall all remember Mr. Page for his patience and understanding and for the kindly encouragement he gave us when we went so unwillingly to school.","zh":"我们都会记得佩奇先生的耐心和体谅，也会记得我们很不情愿地上学时，他给予我们的亲切鼓励。","kind":"narration","speaker":"旁白"},{"en":"A great many former pupils will be attending a farewell dinner in his honour next Thursday.","zh":"下星期四，许多毕业生将出席为他举行的告别晚宴。","kind":"narration","speaker":"旁白"},{"en":"It is a curious coincidence that the day before his retirement, Mr. Page will have been teaching for a total of forty years.","zh":"说来也巧，到退休前一天，佩奇先生的教学生涯将正好满四十年。","kind":"narration","speaker":"旁白"},{"en":"After he has retired, he will devote himself to gardening.","zh":"退休以后，他会专心从事园艺。","kind":"narration","speaker":"旁白"},{"en":"For him, this will be an entirely new hobby.","zh":"对他来说，这将是一项全新的爱好。","kind":"narration","speaker":"旁白"},{"en":"But this does not matter, for, as he has often remarked, one is never too old to learn.","zh":"但这没有关系，因为正如他常说的，活到老，学到老。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l086","number":86,"book":2,"title":"Out of control","paragraphs":[{"index":0,"rows":[{"en":"As the man tried to swing the speedboat round, the steering wheel came away in his hands.","zh":"那个人正想让快艇掉头时，方向盘竟在他手里脱落了。","kind":"narration","speaker":"旁白"},{"en":"He waved desperately to his companion, who had been water skiing for the last fifteen minutes.","zh":"他拼命向同伴挥手示意，那位同伴此前已经连续滑水十五分钟了。","kind":"narration","speaker":"旁白"},{"en":"Both men had hardly had time to realize what was happening when they were thrown violently into the sea.","zh":"两人还没来得及弄清发生了什么，就被猛地甩进了海里。","kind":"narration","speaker":"旁白"},{"en":"The speedboat had struck a buoy, but it continued to move very quickly across the water.","zh":"快艇撞上了一个浮标，却仍在水面上飞速前进。","kind":"narration","speaker":"旁白"},{"en":"Both men had just begun to swim towards the shore, when they noticed with dismay that the speedboat was moving in a circle.","zh":"两人刚开始朝岸边游，就惊恐地发现快艇正在绕圈行驶。","kind":"narration","speaker":"旁白"},{"en":"It now came straight towards them at tremendous speed.","zh":"这时，它正以惊人的速度朝他们直冲过来。","kind":"narration","speaker":"旁白"},{"en":"In less than a minute, it roared past them only a few feet away.","zh":"不到一分钟，它就从离他们只有几英尺远的地方轰鸣着掠过。","kind":"narration","speaker":"旁白"},{"en":"After it had passed, they swam on as quickly as they could because they knew that the boat would soon return.","zh":"快艇驶过之后，两人尽快继续往前游，因为他们知道它很快又会回来。","kind":"narration","speaker":"旁白"},{"en":"They had just had enough time to swim out of danger when the boat again completed a circle.","zh":"他们刚来得及游出危险区域，快艇就又绕完了一圈。","kind":"narration","speaker":"旁白"},{"en":"On this occasion, however, it had slowed down considerably.","zh":"不过这一次，它的速度已经慢了许多。","kind":"narration","speaker":"旁白"},{"en":"The petrol had nearly all been used up.","zh":"汽油几乎全用完了。","kind":"narration","speaker":"旁白"},{"en":"Before long, the noise dropped completely and the boat began to drift gently across the water.","zh":"不久，声音完全消失，快艇开始在水面上缓缓漂流。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l087","number":87,"book":2,"title":"A perfect alibi","paragraphs":[{"index":0,"rows":[{"en":"‘At the time the murder was committed, I was travelling on the 8 o’clock train to London,’ said the man.","zh":"“发生谋杀案的时候，我正在乘坐八点开往伦敦的那班火车，”那人说。","kind":"speech","speaker":"男子"}]},{"index":1,"rows":[{"en":"‘Do you always catch such an early train?’ asked the inspector.","zh":"“你总是乘这么早的火车吗？”探长问。","kind":"speech","speaker":"探长"}]},{"index":2,"rows":[{"en":"‘Of course I do,’ answered the man.","zh":"“当然，”那人回答。","kind":"speech","speaker":"男子"},{"en":"‘I must be at work at 10 o'clock.","zh":"“我必须在十点钟上班。","kind":"speech","speaker":"男子"},{"en":"My employer will confirm that I was there on time.’","zh":"我的雇主可以证明我那天准时到了。”","kind":"speech","speaker":"男子"}]},{"index":3,"rows":[{"en":"‘Would a later train get you to work on time?’ asked the inspector.","zh":"“如果乘晚一班的火车，你还能准时上班吗？”探长问。","kind":"speech","speaker":"探长"}]},{"index":4,"rows":[{"en":"‘I suppose it would, but I never catch a later train.’","zh":"“我想可以，不过我从来不乘晚一班的火车。”","kind":"speech","speaker":"男子"}]},{"index":5,"rows":[{"en":"‘At what time did you arrive at the station?’","zh":"“你几点到的车站？”","kind":"speech","speaker":"探长"}]},{"index":6,"rows":[{"en":"‘At ten to eight.","zh":"“七点五十分。","kind":"speech","speaker":"男子"},{"en":"I bought a paper and waited for the train.’","zh":"我买了份报纸，等着火车来。”","kind":"speech","speaker":"男子"}]},{"index":7,"rows":[{"en":"‘And you didn’t notice anything unusual?’","zh":"“那么，你没有注意到什么异常吗？”","kind":"speech","speaker":"探长"}]},{"index":8,"rows":[{"en":"‘Of course not.’","zh":"“当然没有。”","kind":"speech","speaker":"男子"}]},{"index":9,"rows":[{"en":"‘I suggest,’ said the inspector, ‘that you are not telling the truth.","zh":"“我认为，”探长说，“你没有说实话。","kind":"speech","speaker":"探长"},{"en":"I suggest that you did not catch the 8 o'clock train, but that you caught the 8.25 which would still get you to work on time.","zh":"我认为，你乘的不是八点那班火车，而是八点二十五分那班，那班车照样能让你准时上班。","kind":"speech","speaker":"探长"},{"en":"You see, on the morning of the murder, the 8 o'clock train did not run at all.","zh":"你知道，谋杀案发生的那天早晨，八点那班火车根本没有开。","kind":"speech","speaker":"探长"},{"en":"It broke down at Ferngreen station and was taken off the line.’","zh":"它在芬格林站出了故障，被撤下停运了。”","kind":"speech","speaker":"探长"}]}]},{"lessonId":"nce-b2-eef57c-l088","number":88,"book":2,"title":"Trapped in a mine","paragraphs":[{"index":0,"rows":[{"en":"Six men have been trapped in a mine for seventeen hours.","zh":"六个人已经被困在矿井里十七个小时了。","kind":"narration","speaker":"旁白"},{"en":"If they are not brought to the surface soon they may lose their lives.","zh":"如果不能很快把他们救到地面，他们可能会丧命。","kind":"narration","speaker":"旁白"},{"en":"However, rescue operations are proving difficult.","zh":"然而，救援工作困难重重。","kind":"narration","speaker":"旁白"},{"en":"If explosives are used, vibrations will cause the roof of the mine to collapse.","zh":"如果使用炸药，震动就会使矿井顶部坍塌。","kind":"narration","speaker":"旁白"},{"en":"Rescue workers are therefore drilling a hole on the north side of the mine.","zh":"因此，救援人员正在矿井北侧钻一个洞。","kind":"narration","speaker":"旁白"},{"en":"They intend to bring the men up in a special capsule.","zh":"他们打算用一只特制救生舱把这些人提上来。","kind":"narration","speaker":"旁白"},{"en":"If there had not been a hard layer of rock beneath the soil, they would have completed the job in a few hours.","zh":"如果泥土下面没有一层坚硬的岩石，他们本来几个小时就能完工。","kind":"narration","speaker":"旁白"},{"en":"As it is, they have been drilling for sixteen hours and they still have a long way to go.","zh":"实际情况却是，他们已经钻了十六个小时，仍有很长一段距离需要打通。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, a microphone, which was lowered into the mine two hours ago, has enabled the men to keep in touch with their closest relatives.","zh":"与此同时，两小时前放入矿井的一个麦克风，让被困者能够与最亲近的家人保持联系。","kind":"narration","speaker":"旁白"},{"en":"Though they are running out of food and drink, the men are cheerful and confident that they will get out soon.","zh":"虽然食物和饮水快要用完，这些人仍然情绪乐观，坚信自己很快就能脱困。","kind":"narration","speaker":"旁白"},{"en":"They have been told that rescue operations are progressing smoothly.","zh":"有人告诉他们，救援工作进展顺利。","kind":"narration","speaker":"旁白"},{"en":"If they knew how difficult it was to drill through the hard rock, they would lose heart.","zh":"如果他们知道钻透坚硬的岩石有多困难，就会失去信心。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l089","number":89,"book":2,"title":"A slip of the tongue","paragraphs":[{"index":0,"rows":[{"en":"People will do anything to see a free show — even if it is a bad one.","zh":"为了看一场免费演出，人们什么都愿意做，哪怕演出很差也无所谓。","kind":"narration","speaker":"旁白"},{"en":"When the news got round that a comedy show would be presented at our local cinema by the P. and U. Bird Seed Company, we all rushed to see it.","zh":"消息传来，说P和U鸟食公司要在我们当地的电影院举办一场喜剧演出，我们便都赶去观看。","kind":"narration","speaker":"旁白"},{"en":"We had to queue for hours to get in and there must have been several hundred people present just before the show began.","zh":"我们排了好几个小时的队才能进去，而就在演出开始前，现场想必已经有好几百人了。","kind":"narration","speaker":"旁白"},{"en":"Unfortunately, the show was one of the dullest we have ever seen.","zh":"不幸的是，这是我们看过的最乏味的演出之一。","kind":"narration","speaker":"旁白"},{"en":"Those who failed to get in need not have felt disappointed, as many of the artistes who should have appeared did not come.","zh":"没能进去的人本来不必感到失望，因为许多本该出场的艺人都没有来。","kind":"narration","speaker":"旁白"},{"en":"The only funny things we heard that evening came from the advertiser at the beginning of the programme.","zh":"那天晚上，我们听到的唯一好笑的内容，来自节目开始时的广告报幕员。","kind":"narration","speaker":"旁白"},{"en":"He was obviously very nervous and for some minutes stood awkwardly before the microphone.","zh":"他显然十分紧张，在麦克风前局促地站了好几分钟。","kind":"narration","speaker":"旁白"},{"en":"As soon as he opened his mouth, everyone burst out laughing.","zh":"他刚一开口，所有人就哄堂大笑。","kind":"narration","speaker":"旁白"},{"en":"We all know what the poor man should have said, but what he actually said was: ‘This is the Poo and Ee Seed Bird Company.","zh":"我们都知道这个可怜的人本来应该说什么，可他实际上说的却是：“这里是普和伊籽鸟公司。","kind":"mixed","speaker":"旁白与广告报幕员","breakBefore":true},{"en":"Good ladies, evening and gentlemen!’","zh":"好女士们，晚上和先生们！”","kind":"speech","speaker":"广告报幕员"}]}]},{"lessonId":"nce-b2-eef57c-l090","number":90,"book":2,"title":"What's for supper?","paragraphs":[{"index":0,"rows":[{"en":"Fish and chips has always been a favourite dish in Britain, but as the oceans have been overfished, fish has become more and more expensive.","zh":"炸鱼配薯条一直是英国人喜爱的一道菜，但由于海洋遭到过度捕捞，鱼变得越来越贵。","kind":"narration","speaker":"旁白"},{"en":"So it comes as a surprise to learn that giant fish are terrifying the divers on North Sea oil rigs.","zh":"因此，听说巨鱼正让北海石油钻井平台的潜水员惊恐不已，实在令人吃惊。","kind":"narration","speaker":"旁白"},{"en":"Oil rigs have to be repaired frequently and divers, who often have to work in darkness a hundred feet under water, have been frightened out of their wits by giant fish bumping into them as they work.","zh":"钻井平台需要经常维修，潜水员往往得在水下一百英尺深的黑暗中工作，而他们工作时撞来的巨鱼，把他们吓得魂不附体。","kind":"narration","speaker":"旁白"},{"en":"Now they have had special cages made to protect them from these monsters.","zh":"现在，他们已经请人特制了一些笼子，以保护自己免受这些巨物的侵扰。","kind":"narration","speaker":"旁白"},{"en":"The fish are not sharks or killer whales, but favourite eating varieties like cod and skate which grow to unnatural sizes, sometimes as much as twelve feet in length.","zh":"这些鱼并不是鲨鱼或虎鲸，而是人们喜爱食用的鳕鱼、鳐鱼等品种，它们长到了异乎寻常的大小，有时长达十二英尺。","kind":"narration","speaker":"旁白"},{"en":"Three factors have caused these fish to grow so large: the warm water round the hot oil pipes under the sea; the plentiful supply of food thrown overboard by the crews on the rigs; the total absence of fishing boats around the oil rigs.","zh":"三个因素使这些鱼长得如此巨大：海底热输油管道周围温暖的海水；钻井平台工作人员扔下海的大量食物；以及平台周围完全没有渔船。","kind":"narration","speaker":"旁白"},{"en":"As a result, the fish just eat and eat and grow and grow in the lovely warm water.","zh":"结果，这些鱼就在舒适温暖的水里，吃了又吃，长了又长。","kind":"narration","speaker":"旁白"},{"en":"Who cats who?","zh":"究竟是谁吃谁呢？","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l091","number":91,"book":2,"title":"Three men in a basket","paragraphs":[{"index":0,"rows":[{"en":"A pilot noticed a balloon which seemed to be making for a Royal Air Force Station nearby.","zh":"一名飞行员发现了一个气球，它似乎正朝附近的皇家空军基地飞去。","kind":"narration","speaker":"旁白"},{"en":"He informed the station at once, but no one there was able to explain the mystery.","zh":"他立即通知了基地，但那里没有人能解释这是怎么回事。","kind":"narration","speaker":"旁白"},{"en":"The officer in the control tower was very angry when he heard the news, because balloons can be a great danger to aircraft.","zh":"控制塔上的军官听到消息后十分生气，因为气球可能给飞机带来很大危险。","kind":"narration","speaker":"旁白"},{"en":"He said that someone might be spying on the station and the pilot was ordered to keep track of the strange object.","zh":"他说，可能有人正在侦察基地，于是飞行员接到命令，跟踪这个奇怪的物体。","kind":"narration","speaker":"旁白"},{"en":"The pilot managed to circle the balloon for some time.","zh":"飞行员设法围绕气球盘旋了一阵子。","kind":"narration","speaker":"旁白"},{"en":"He could make out three men in a basket under it and one of them was holding a pair of binoculars.","zh":"他能看清气球下面的吊篮里有三个人，其中一人拿着一副双筒望远镜。","kind":"narration","speaker":"旁白"},{"en":"When the balloon was over the station, the pilot saw one of the men taking photographs.","zh":"气球飞到基地上空时，飞行员看见其中一人在拍照。","kind":"narration","speaker":"旁白"},{"en":"Soon afterwards, the balloon began to descend and it landed near an airfield.","zh":"没过多久，气球开始下降，落在一处机场附近。","kind":"narration","speaker":"旁白"},{"en":"The police were called in, but they could not arrest anyone, for the basket contained two Members of Parliament and the Commanding Officer of the station!","zh":"警察被叫来了，却无法逮捕任何人，因为吊篮里坐着的是两名议员和这座基地的指挥官！","kind":"narration","speaker":"旁白"},{"en":"As the Commanding Officer explained later, one half of the station did not know what the other half was doing!","zh":"正如指挥官后来解释的，基地里一半的人不知道另一半的人在做什么！","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l092","number":92,"book":2,"title":"Asking for trouble","paragraphs":[{"index":0,"rows":[{"en":"It must have been about two in the morning when I returned home.","zh":"我回到家时，想必已经是凌晨两点左右了。","kind":"narration","speaker":"旁白"},{"en":"I tried to wake up my wife by ringing the doorbell, but she was fast asleep, so I got a ladder from the shed in the garden, put it against the wall, and began climbing towards the bedroom window.","zh":"我按门铃，想叫醒妻子，可她睡得很熟，于是我从花园的棚子里拿来一架梯子，靠在墙上，开始往卧室窗户爬。","kind":"narration","speaker":"旁白"},{"en":"I was almost there when a sarcastic voice below said, ‘I don’t think the windows need cleaning at this time of the night.’","zh":"我差不多爬到那里时，下面传来一个讥讽的声音：“我想，不用在半夜这个时候擦窗户吧。”","kind":"mixed","speaker":"旁白与警察","breakBefore":true},{"en":"I looked down and nearly fell off the ladder when I saw a policeman.","zh":"我往下一看，发现是个警察，差点从梯子上掉下来。","kind":"narration","speaker":"旁白"},{"en":"I immediately regretted answering in the way I did, but I said, ‘I enjoy cleaning windows at night.’","zh":"我马上就为自己的回答后悔了，可我当时说的是：“我就喜欢晚上擦窗户。”","kind":"mixed","speaker":"旁白与我","breakBefore":true}]},{"index":1,"rows":[{"en":"‘So do I,’ answered the policeman in the same tone.","zh":"“我也一样，”警察用同样的口气回答。","kind":"speech","speaker":"警察"},{"en":"‘Excuse my interrupting you.","zh":"“请原谅我打断你。","kind":"speech","speaker":"警察"},{"en":"I hate to interrupt a man when he’s busy working, but would you mind coming with me to the station?’","zh":"我不愿意打扰忙着干活的人，不过，你介意跟我到警察局走一趟吗？”","kind":"speech","speaker":"警察"}]},{"index":2,"rows":[{"en":"‘Well, I'd prefer to stay here,’ I said.","zh":"“嗯，我还是愿意留在这里，”我说。","kind":"speech","speaker":"我"},{"en":"‘You see, I've forgotten my key.’","zh":"“你看，我忘带钥匙了。”","kind":"speech","speaker":"我"}]},{"index":3,"rows":[{"en":"‘Your what?’ he called.","zh":"“你的什么？”他大声问。","kind":"speech","speaker":"警察"}]},{"index":4,"rows":[{"en":"‘My key,’ I shouted.","zh":"“我的钥匙！”我喊道。","kind":"speech","speaker":"我"}]},{"index":5,"rows":[{"en":"Fortunately, the shouting woke up my wife who opened the window just as the policeman had started to climb towards me.","zh":"幸好，喊声吵醒了妻子，警察刚开始朝我爬上来，她就打开了窗户。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l093","number":93,"book":2,"title":"A noble gift","paragraphs":[{"index":0,"rows":[{"en":"One of the most famous monuments in the world, the Statue of Liberty, was presented to the United States of America in the nineteenth century by the people of France.","zh":"自由女神像是世界上最著名的纪念性建筑之一，是法国人民在十九世纪赠送给美国的。","kind":"narration","speaker":"旁白"},{"en":"The great statue, which was designed by the sculptor Auguste Bartholdi, took ten years to complete.","zh":"这座宏伟的雕像由雕塑家奥古斯特·巴托尔迪设计，历时十年才完成。","kind":"narration","speaker":"旁白"},{"en":"The actual figure was made of copper supported by a metal framework which had been especially constructed by Eiffel.","zh":"雕像本体用铜制成，由一副金属框架支撑，这副框架是埃菲尔专门建造的。","kind":"narration","speaker":"旁白"},{"en":"Before it could be transported to the United States, a site had to be found for it and a pedestal had to be built.","zh":"在把雕像运往美国以前，必须先为它选好地点，建起基座。","kind":"narration","speaker":"旁白"},{"en":"The site chosen was an island at the entrance of New York Harbour.","zh":"最终选定的地点是纽约港入口处的一个小岛。","kind":"narration","speaker":"旁白"},{"en":"By 1884, a statue which was 151 feet tall had been erected in Paris.","zh":"到1884年，一座高一百五十一英尺的雕像已经在巴黎竖起。","kind":"narration","speaker":"旁白"},{"en":"The following year, it was taken to pieces and sent to America.","zh":"第二年，人们把它拆开，运往美国。","kind":"narration","speaker":"旁白"},{"en":"By the end of October 1886, the statue had been put together again and it was officially presented to the American people by Bartholdi.","zh":"到1886年10月底，雕像已经重新组装完毕，由巴托尔迪正式赠送给美国人民。","kind":"narration","speaker":"旁白"},{"en":"Ever since then, the great monument has been a symbol of liberty for the millions of people who have passed through New York Harbour to make their homes in America.","zh":"从那以后，对于经过纽约港、前往美国安家落户的数百万人来说，这座伟大的纪念像一直是自由的象征。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l094","number":94,"book":2,"title":"Future champions","paragraphs":[{"index":0,"rows":[{"en":"Experiments have proved that children can be instructed in swimming at a very early age.","zh":"实验证明，孩子很小的时候就能接受游泳训练。","kind":"narration","speaker":"旁白"},{"en":"At a special swimming pool in Los Angeles, children become expert at holding their breath under water even before they can walk.","zh":"在洛杉矶一座专门的游泳池里，孩子们还不会走路，就已经很擅长在水下屏气。","kind":"narration","speaker":"旁白"},{"en":"Babies of two months old do not appear to be reluctant to enter the water.","zh":"两个月大的婴儿似乎并不抗拒下水。","kind":"narration","speaker":"旁白"},{"en":"It is not long before they are so accustomed to swimming that they can pick up weights from the floor of the pool.","zh":"没过多久，他们就十分习惯游泳，能够从池底拾起重物。","kind":"narration","speaker":"旁白"},{"en":"A game that is very popular with these young swimmers is the underwater tricycle race.","zh":"这些小小游泳者非常喜欢的一种游戏，是水下三轮车比赛。","kind":"narration","speaker":"旁白"},{"en":"Tricycles are lined up on the floor of the pool seven feet under water.","zh":"三轮车在水面下七英尺深的池底排成一行。","kind":"narration","speaker":"旁白"},{"en":"The children compete against each other to reach the other end of the pool.","zh":"孩子们互相比赛，看谁先到达游泳池的另一端。","kind":"narration","speaker":"旁白"},{"en":"Many pedal their tricycles, but most of them prefer to push or drag them.","zh":"不少孩子踩着三轮车的踏板前进，但大多数更愿意推着或拖着车走。","kind":"narration","speaker":"旁白"},{"en":"Some children can cover the whole length of the pool without coming up for breath even once.","zh":"有些孩子能够游完整个泳池，连一次都不用浮上水面换气。","kind":"narration","speaker":"旁白"},{"en":"Whether they will ever become future Olympic champions, only time will tell.","zh":"他们将来是否会成为奥运会冠军，只有时间才能回答。","kind":"narration","speaker":"旁白"},{"en":"Meanwhile, they should encourage those among us who cannot swim five yards before they are gasping for air.","zh":"与此同时，他们应该能鼓励我们当中那些还游不到五码就已经上气不接下气的人。","kind":"narration","speaker":"旁白"}]}]},{"lessonId":"nce-b2-eef57c-l095","number":95,"book":2,"title":"A fantasy","paragraphs":[{"index":0,"rows":[{"en":"When the Ambassador of Escalopia returned home for lunch, his wife got a shock.","zh":"艾斯卡洛比亚的大使回家吃午饭时，他的妻子吓了一跳。","kind":"narration","speaker":"旁白"},{"en":"He looked pale and his clothes were in a frightful state.","zh":"他脸色苍白，衣服也糟糕得不像样。","kind":"narration","speaker":"旁白"}]},{"index":1,"rows":[{"en":"‘What has happened?’ she asked.","zh":"“出了什么事？”她问。","kind":"speech","speaker":"大使夫人"},{"en":"‘How did your clothes get into such a mess?’","zh":"“你的衣服怎么弄得这么乱？”","kind":"speech","speaker":"大使夫人"}]},{"index":2,"rows":[{"en":"‘A fire extinguisher, my dear,’ answered the Ambassador drily.","zh":"“是灭火器弄的，亲爱的，”大使淡淡地回答。","kind":"speech","speaker":"大使"},{"en":"‘University students set the Embassy on fire this morning.’","zh":"“今天早晨，大学生们把大使馆点着了。”","kind":"speech","speaker":"大使"}]},{"index":3,"rows":[{"en":"‘Good heavens!’ exclaimed his wife.","zh":"“天哪！”妻子惊叫道。","kind":"speech","speaker":"大使夫人"},{"en":"‘And where were you at the time?’","zh":"“那时你在哪儿？”","kind":"speech","speaker":"大使夫人"}]},{"index":4,"rows":[{"en":"‘I was in my office as usual,’ answered the Ambassador.","zh":"“我像往常一样待在办公室里，”大使回答。","kind":"speech","speaker":"大使"},{"en":"‘The fire broke out in the basement.","zh":"“地下室起了火。","kind":"speech","speaker":"大使"},{"en":"I went down immediately, of course, and that fool, Horst, aimed a fire extinguisher at me.","zh":"我当然立刻下楼去了，可霍斯特那个笨蛋把灭火器对准了我。","kind":"speech","speaker":"大使"},{"en":"He thought I was on fire.","zh":"他以为我身上着火了。","kind":"speech","speaker":"大使"},{"en":"I must definitely get that fellow posted.’","zh":"我一定得把那家伙调走。”","kind":"speech","speaker":"大使"}]},{"index":5,"rows":[{"en":"The Ambassador's wife went on asking questions, when she suddenly noticed a big hole in her husband's hat.","zh":"大使夫人还在接着提问，忽然发现丈夫的帽子上有个大洞。","kind":"narration","speaker":"旁白"}]},{"index":6,"rows":[{"en":"‘And how can you explain that?’ she asked.","zh":"“那这个你怎么解释？”她问。","kind":"speech","speaker":"大使夫人"}]},{"index":7,"rows":[{"en":"‘Oh, that,’ said the Ambassador.","zh":"“哦，那个呀，”大使说。","kind":"speech","speaker":"大使"},{"en":"‘Someone fired a shot through my office window.","zh":"“有人开了一枪，子弹穿过了我办公室的窗户。","kind":"speech","speaker":"大使"},{"en":"Accurate, don’t you think?","zh":"打得挺准，你说是不是？","kind":"speech","speaker":"大使"},{"en":"Fortunately, I wasn’t wearing it at the time.","zh":"幸好，那时我没有戴那顶帽子。","kind":"speech","speaker":"大使"},{"en":"If I had been, I would not have been able to get home for lunch.’","zh":"要是戴着，我就没法回家吃午饭了。”","kind":"speech","speaker":"大使"}]}]},{"lessonId":"nce-b2-eef57c-l096","number":96,"book":2,"title":"The dead return","paragraphs":[{"index":0,"rows":[{"en":"A Festival for the Dead is held once a year in Japan.","zh":"日本每年举行一次祭亡节。","kind":"narration","speaker":"旁白"},{"en":"This festival is a cheerful occasion, for on this day, the dead are said to return to their homes and they are welcomed by the living.","zh":"这个节日气氛欢快，因为据说在这一天，亡者会回到家中，受到生者的欢迎。","kind":"narration","speaker":"旁白"},{"en":"As they are expected to be hungry after their long journey, food is laid out for them.","zh":"人们认为，亡者经过长途跋涉后会感到饥饿，因此为他们摆好食物。","kind":"narration","speaker":"旁白"},{"en":"Specially-made lanterns are hung outside each house to help the dead to find their way.","zh":"每家屋外都挂起特制的灯笼，帮助亡者认路。","kind":"narration","speaker":"旁白"},{"en":"All night long, people dance and sing.","zh":"人们通宵载歌载舞。","kind":"narration","speaker":"旁白"},{"en":"In the early morning, the food that had been laid out for the dead is thrown into a river or into the sea as it is considered unlucky for anyone living to eat it.","zh":"到了清晨，先前为亡者摆好的食物会被扔进河里或海里，因为活人吃这些食物被认为不吉利。","kind":"narration","speaker":"旁白"},{"en":"In towns that are near the sea, the tiny lanterns which had been hung in the streets the night before, are placed into the water when the festival is over.","zh":"在靠海的城镇，节日结束时，人们会把前一夜挂在街上的小灯笼放进水中。","kind":"narration","speaker":"旁白"},{"en":"Thousands of lanterns slowly drift out to sea guiding the dead on their return journey to the other world.","zh":"成千上万盏灯笼缓缓漂向大海，指引亡者踏上返回另一个世界的路程。","kind":"narration","speaker":"旁白"},{"en":"This is a moving spectacle, for crowds of people stand on the shore watching the lanterns drifting away until they can be seen no more.","zh":"这是一个感人的景象，因为岸边站着成群的人，目送灯笼渐渐漂远，直到再也看不见。","kind":"narration","speaker":"旁白"}]}]}]};
